def _fiendish_asset_root() -> str:
    try:
        env_root = str(os.environ.get("FIENDISH_RELEASE_DIR", "") or "").strip()
        if env_root:
            return str(Path(env_root).expanduser().resolve())
    except Exception:
        pass
    return os.path.dirname(os.path.abspath(__file__))


