def detect_display_profile(cols: int, rows: int) -> DisplayProfile:
    """Auto-detect best display profile based on terminal dimensions."""
    if cols >= 120 and rows >= 35:
        return DISPLAY_PROFILES["highres"]
    elif cols >= 80 and rows >= 24:
        return DISPLAY_PROFILES["standard"]
    else:
        return DISPLAY_PROFILES["minimal"]

def load_config():
    path = Path.home() / ".ogre_shader_config.json"
    default = {
        "grin_factor": 1.0, 
        "typing_speed": 0.015, 
        "sound_enabled": True, 
        "fork_timeout": 4.0,
        "no_dialogue_mode": False,
        "display_profile": "auto",  # "auto", "standard", "highres", "minimal"
        "oy_loadout": list(DEFAULT_OY_LOADOUT),
    }
    if path.exists():
        try:
            with open(path) as f:
                return {**default, **json.load(f)}
        except: pass
    return default


