@dataclass
class Vibe:
    verbal: int = 0
    physical: int = 0
    silent: int = 0
    stammers: int = 0
    intensity: int = 0
    tenderness: int = 0
    
    hits: int = 0
    misses: int = 0
    combo: int = 0
    max_combo: int = 0
    
    slips: int = 0
    wrong_holes: int = 0
    escapes: int = 0
    
    forks_total: int = 0
    milestones_hit: List[str] = field(default_factory=list)
    current_arc: Optional[str] = None
    arc_phase: str = "calibration"
    session_time: float = 0.0
    climax_reached: bool = False
    
    # Special mode tracking
    bathroom_trips: int = 0
    love_bunny_sessions: int = 0
    starving_sessions: int = 0
    scared_moments: int = 0
    sleepy_moments: int = 0
    commands_obeyed: int = 0
    woofs: int = 0
    cycles_completed: int = 0
    
    # Mode state
    in_love_bunny: bool = False
    in_starving: bool = False
    in_hump_dog: bool = False
    bunny_combo: int = 0
    hump_dog_unlocked: bool = False
    edge_count: int = 0
    
    def dominant_style(self) -> str:
        styles = {"verbal": self.verbal, "physical": self.physical, "silent": self.silent, "stammers": self.stammers}
        if max(styles.values()) == 0:
            return "balanced"
        return max(styles, key=styles.get)
    
    def accuracy(self) -> float:
        total = self.hits + self.misses
        return self.hits / total if total > 0 else 0.75


