# ═══════════════════════════════════════════════════════════════════════════════
#                    DIALOGUE PORT SYSTEM
#              Every coupled dialogue has entry/exit ports for clean flow
#              Prevents mid-conversation frame swaps that break immersion
# ═══════════════════════════════════════════════════════════════════════════════

class DialoguePort:
    """
    Defines entry and exit states for dialogue sequences.
    
    ENTRY PORT: What emotional/game state allows entering this dialogue?
    EXIT PORT: What state does the dialogue leave the characters in?
    
    Sequences can only chain if exit_port matches next entry_port.
    Frame changes (lightmap swaps) only happen at port boundaries.
    """
    # Emotional states
    NEUTRAL = "neutral"          # Calm, baseline
    TENDER = "tender"            # Soft, vulnerable moment
    PLAYFUL = "playful"          # Teasing, light
    HEATED = "heated"            # Building intensity
    DESPERATE = "desperate"      # High need, urgent
    AFTERGLOW = "afterglow"      # Post-climax calm
    
    # Special states
    INTERRUPTED = "interrupted"  # Something broke the flow
    WAITING = "waiting"          # Paused, anticipating
    
    @staticmethod
    def compatible(exit_port: str, entry_port: str) -> bool:
        """Check if exit_port can flow into entry_port."""
        # Define compatibility matrix
        compat = {
            "neutral": ["neutral", "tender", "playful", "heated"],
            "tender": ["tender", "neutral", "heated", "afterglow"],
            "playful": ["playful", "neutral", "tender", "heated"],
            "heated": ["heated", "desperate", "playful", "tender"],
            "desperate": ["desperate", "heated", "afterglow"],
            "afterglow": ["afterglow", "neutral", "tender"],
            "interrupted": ["neutral", "waiting", "tender"],  # Recovery
            "waiting": ["neutral", "tender", "playful", "heated"],
        }
        return entry_port in compat.get(exit_port, [])


@dataclass
class PortedDialogue:
    """A dialogue sequence with defined entry and exit ports."""
    id: str
    entry_port: str
    exit_port: str
    lines: List[Tuple[str, str]]  # [(speaker, text), ...]
    
    # Optional conditions
    min_intensity: float = 0.0
    max_intensity: float = 1.0
    requires_mode: str = None
    content_tier: int = 0  # Minimum content tier required


# Dialogue manager tracks current port state
@dataclass  
class DialogueFlowState:
    """Tracks current dialogue flow for port-aware sequencing."""
    current_port: str = "neutral"
    in_sequence: bool = False
    sequence_id: str = ""
    frame_change_queued: bool = False
    queued_frame: str = ""
    
    def can_start(self, dialogue: PortedDialogue) -> bool:
        """Check if we can start this dialogue from current port."""
        if self.in_sequence:
            return False  # Can't interrupt mid-sequence
        return DialoguePort.compatible(self.current_port, dialogue.entry_port)
    
    def start_sequence(self, dialogue: PortedDialogue):
        """Begin a dialogue sequence."""
        self.in_sequence = True
        self.sequence_id = dialogue.id
        # Port doesn't change until sequence completes
    
    def end_sequence(self, dialogue: PortedDialogue):
        """Complete a dialogue sequence, update port."""
        self.in_sequence = False
        self.sequence_id = ""
        self.current_port = dialogue.exit_port
        
        # Process queued frame change now that sequence is done
        if self.frame_change_queued:
            self.frame_change_queued = False
            return self.queued_frame
        return None
    
    def queue_frame_change(self, frame: str):
        """Queue a frame change to happen after current sequence."""
        if self.in_sequence:
            self.frame_change_queued = True
            self.queued_frame = frame
        # If not in sequence, caller should apply immediately


