# ═══════════════════════════════════════════════════════════════════════════════
#                    BRANCHING VIGNETTES
#              Every scene can go three ways based on power_dynamic
# ═══════════════════════════════════════════════════════════════════════════════

@dataclass
class BranchingVignette:
    """A vignette with three possible branches based on power dynamic."""
    vignette_id: str
    trigger: str              # What triggers this vignette
    context: str              # Narrative context
    
    # The three branches
    fiend_dom: List[Tuple[str, str]]    # power > 0.3
    bird_dom: List[Tuple[str, str]]     # power < -0.3
    contested: List[Tuple[str, str]]     # -0.3 < power < 0.3
    
    # What happens after each branch
    fiend_dom_effect: Dict[str, float]
    bird_dom_effect: Dict[str, float]
    contested_effect: Dict[str, float]
    
    def get_branch(self, power_dynamic: float) -> Tuple[List[Tuple[str, str]], Dict[str, float]]:
        """Get the appropriate branch based on power dynamic."""
        if power_dynamic > 0.3:
            return self.fiend_dom, self.fiend_dom_effect
        elif power_dynamic < -0.3:
            return self.bird_dom, self.bird_dom_effect
        else:
            return self.contested, self.contested_effect


