# ═══════════════════════════════════════════════════════════════════════════════
#                    TRANSITION ANIMATIONS
#              Moving between poses - dissolve, slide, turn
# ═══════════════════════════════════════════════════════════════════════════════

def create_dissolve_transition(duration_ms: int = 500, steps: int = 5) -> Animation:
    """Create a dissolve transition between two poses."""
    frames = []
    step_duration = duration_ms // steps
    for i in range(steps):
        opacity = 1.0 - (i / (steps - 1))  # 1.0 → 0.0
        frames.append(AnimationFrame(i, duration_ms=step_duration, opacity=opacity))
    return Animation(
        animation_id="dissolve",
        animation_type=AnimationType.DISSOLVE,
        frames=frames,
        loop=False,
        interruptible=True,
    )


def create_slide_transition(direction: str, distance: int = 10, duration_ms: int = 400) -> Animation:
    """Create a slide transition. Direction: 'left', 'right', 'up', 'down'."""
    frames = []
    steps = 5
    step_duration = duration_ms // steps
    
    for i in range(steps):
        progress = i / (steps - 1)  # 0.0 → 1.0
        offset = int(distance * progress)
        
        if direction == "left":
            frames.append(AnimationFrame(i, duration_ms=step_duration, x_offset=-offset))
        elif direction == "right":
            frames.append(AnimationFrame(i, duration_ms=step_duration, x_offset=offset))
        elif direction == "up":
            frames.append(AnimationFrame(i, duration_ms=step_duration, y_offset=-offset))
        elif direction == "down":
            frames.append(AnimationFrame(i, duration_ms=step_duration, y_offset=offset))
    
    return Animation(
        animation_id=f"slide_{direction}",
        animation_type=AnimationType.SLIDE,
        frames=frames,
        loop=False,
    )


# ═══════════════════════════════════════════════════════════════════════════════
#                    POSE ORIENTATION TRACKING
#              Track facing direction for intelligent transitions
# ═══════════════════════════════════════════════════════════════════════════════

class PoseOrientation(Enum):
    """Which way the pose is facing."""
    FRONT = "front"           # Facing camera
    BACK = "back"             # Facing away
    LEFT = "left"             # Profile left
    RIGHT = "right"           # Profile right
    THREE_QUARTER_LEFT = "3q_left"
    THREE_QUARTER_RIGHT = "3q_right"


# Map poses to their orientations
POSE_ORIENTATIONS = {
    "front_presence": PoseOrientation.FRONT,
    "coy_cheek": PoseOrientation.THREE_QUARTER_RIGHT,  # Looking over shoulder
    "laying_smile": PoseOrientation.FRONT,  # Laying but facing up
    "stand_backfacing": PoseOrientation.BACK,
    "strut": PoseOrientation.THREE_QUARTER_LEFT,  # Walking, slight angle
    "squat": PoseOrientation.FRONT,
    "downward": PoseOrientation.FRONT,  # Looking down but front-facing
    "angled_collapse": PoseOrientation.THREE_QUARTER_LEFT,
    "outhouse": PoseOrientation.THREE_QUARTER_RIGHT,
    "face": PoseOrientation.FRONT,  # Close-up
}

# Transition paths - which intermediate orientations to go through
TURN_PATHS = {
    (PoseOrientation.FRONT, PoseOrientation.BACK): [PoseOrientation.THREE_QUARTER_LEFT, PoseOrientation.LEFT],
    (PoseOrientation.BACK, PoseOrientation.FRONT): [PoseOrientation.THREE_QUARTER_RIGHT, PoseOrientation.RIGHT],
    (PoseOrientation.FRONT, PoseOrientation.THREE_QUARTER_LEFT): [],  # Direct
    (PoseOrientation.FRONT, PoseOrientation.THREE_QUARTER_RIGHT): [],  # Direct
    (PoseOrientation.LEFT, PoseOrientation.RIGHT): [PoseOrientation.FRONT],  # Go through front
}


# ═══════════════════════════════════════════════════════════════════════════════
#                    ANIMATION ENGINE
#              Applies animations to lightmap frames
# ═══════════════════════════════════════════════════════════════════════════════

class MicroAnimationEngine:
    """
    Engine that applies micro-animations to lightmap ASCII frames.
    Handles breathing, reactions, head turns, gestures, and transitions.
    """
    
    def __init__(self):
        self.current_animation: Optional[Animation] = None
        self.animation_start_time: float = 0.0
        self.current_frame_idx: int = 0
        self.idle_animation: Animation = BREATHING_NORMAL
        self.pose_orientation: PoseOrientation = PoseOrientation.FRONT
        self.current_pose_name: str = ""
        
        # Animation queue for sequencing
        self.animation_queue: List[Animation] = []
        
        # Overlay animations (run simultaneously with main animation)
        self.overlay_animation: Optional[Animation] = None
        self.overlay_start_time: float = 0.0
        
        # Head direction tracking
        self.head_direction: HeadDirection = HeadDirection.CENTER
        self.head_animation_active: bool = False
        
        # For transitions
        self.transitioning: bool = False
        self.source_pose_lines: List[str] = []
        self.target_pose_lines: List[str] = []
    
    def set_pose(self, pose_name: str):
        """Set current pose and update breathing to match."""
        self.current_pose_name = pose_name
        self.pose_orientation = POSE_ORIENTATIONS.get(pose_name, PoseOrientation.FRONT)
    
    def set_idle_animation(self, breathing_type: str = "normal", pose_name: str = None):
        """Set the idle breathing animation, optionally pose-specific."""
        pose = pose_name or self.current_pose_name
        
        # Try pose-specific breathing first
        if pose and pose in POSE_BREATHING_VARIANTS:
            variants = POSE_BREATHING_VARIANTS[pose]
            if breathing_type in variants:
                self.idle_animation = variants[breathing_type]
                return
        
        # Fall back to generic breathing
        if breathing_type == "slow":
            self.idle_animation = BREATHING_SLOW
        elif breathing_type == "fast":
            self.idle_animation = BREATHING_FAST
        elif breathing_type == "exhausted":
            self.idle_animation = BREATHING_EXHAUSTED
        else:
            self.idle_animation = BREATHING_NORMAL
    
    def trigger_animation(self, animation: Animation, interrupt: bool = True):
        """Trigger a new animation."""
        if self.current_animation and not self.current_animation.interruptible and not interrupt:
            # Queue it instead
            self.animation_queue.append(animation)
            return
        
        self.current_animation = animation
        self.animation_start_time = time.time()
        self.current_frame_idx = 0
    
    def trigger_overlay(self, animation: Animation):
        """Trigger an overlay animation that runs with the main animation."""
        self.overlay_animation = animation
        self.overlay_start_time = time.time()
    
    def trigger_reaction(self, reaction_type: str):
        """Trigger a reaction animation by name."""
        reactions = {
            "startle": STARTLE,
            "slump": SLUMP,
            "flinch": FLINCH,
            "idea": IDEA_JUMP,
            "take": TAKE_REACTION,
        }
        if reaction_type in reactions:
            self.trigger_animation(reactions[reaction_type])
    
    def trigger_head_turn(self, direction: str):
        """Trigger a head turn animation."""
        if direction in HEAD_ANIMATIONS:
            self.trigger_overlay(HEAD_ANIMATIONS[direction])
            self.head_animation_active = True
            # Update head direction after animation
            dir_map = {
                "left": HeadDirection.LEFT,
                "right": HeadDirection.RIGHT,
                "away": HeadDirection.AWAY,
                "down": HeadDirection.DOWN,
                "up": HeadDirection.UP,
                "snap": HeadDirection.RIGHT,
            }
            self.head_direction = dir_map.get(direction, HeadDirection.CENTER)
    
    def trigger_gesture(self, gesture_type: str):
        """Trigger a gesture animation."""
        if gesture_type in GESTURE_LIBRARY:
            self.trigger_animation(GESTURE_LIBRARY[gesture_type])
    
    def trigger_turnaround(self, sequence_id: str):
        """Trigger a turnaround animation."""
        if sequence_id in TURNAROUND_ANIMATIONS:
            self.trigger_animation(TURNAROUND_ANIMATIONS[sequence_id])
    
    def trigger_compound(self, compound_id: str):
        """Trigger a compound animation (base + overlays)."""
        if compound_id in COMPOUND_ANIMATIONS:
            compound = COMPOUND_ANIMATIONS[compound_id]
            self.trigger_animation(compound.base_animation)
            if compound.overlay_animations:
                self.trigger_overlay(compound.overlay_animations[0])
    
    def get_current_frame(self) -> AnimationFrame:
        """Get the current animation frame based on elapsed time."""
        now = time.time()
        
        # If no active animation, use idle
        animation = self.current_animation or self.idle_animation
        
        elapsed_ms = (now - self.animation_start_time) * 1000
        
        # Find current frame
        cumulative_ms = 0
        for i, frame in enumerate(animation.frames):
            cumulative_ms += frame.duration_ms
            if elapsed_ms < cumulative_ms:
                return frame
        
        # Animation complete
        if animation.loop:
            # Reset and continue
            self.animation_start_time = now
            self.current_frame_idx = 0
            return animation.frames[0]
        else:
            # Animation done, check queue or return to idle
            if self.animation_queue:
                next_anim = self.animation_queue.pop(0)
                self.trigger_animation(next_anim)
                return self.get_current_frame()
            else:
                self.current_animation = None
                self.animation_start_time = now
                return self.idle_animation.frames[0]
    
    def apply_frame_to_lines(self, lines: List[str], frame: AnimationFrame) -> List[str]:
        """Apply animation frame transforms to lightmap lines."""
        if not lines:
            return lines
        
        result = lines.copy()
        
        # Determine which rows to affect
        start_row = 0
        end_row = len(lines)
        if frame.row_range:
            start_row = max(0, frame.row_range[0])
            end_row = min(len(lines), frame.row_range[1])
        
        # Apply vertical offset (shift rows)
        if frame.y_offset != 0:
            result = self._apply_y_offset(result, frame.y_offset, start_row, end_row)
        
        # Apply horizontal offset (shift columns)
        if frame.x_offset != 0:
            result = self._apply_x_offset(result, frame.x_offset, start_row, end_row)
        
        # Apply scale (compress/expand) - simplified version
        if frame.scale_y != 1.0:
            result = self._apply_y_scale(result, frame.scale_y, start_row, end_row)
        
        return result
    
    def _apply_y_offset(self, lines: List[str], offset: int, start: int, end: int) -> List[str]:
        """Shift rows vertically."""
        result = lines.copy()
        
        if offset < 0:  # Shift up
            for i in range(start, end):
                target = i + offset
                if 0 <= target < len(result) and i < len(lines):
                    # Blend with what's there
                    result[target] = lines[i]
            # Clear the vacated rows at bottom of range
            for i in range(max(start, end + offset), end):
                if i < len(result):
                    result[i] = '░' * len(lines[0]) if lines else ''
        
        elif offset > 0:  # Shift down
            for i in range(end - 1, start - 1, -1):
                target = i + offset
                if 0 <= target < len(result) and i < len(lines):
                    result[target] = lines[i]
            # Clear the vacated rows at top of range
            for i in range(start, min(end, start + offset)):
                if i < len(result):
                    result[i] = '░' * len(lines[0]) if lines else ''
        
        return result
    
    def _apply_x_offset(self, lines: List[str], offset: int, start: int, end: int) -> List[str]:
        """Shift columns horizontally."""
        result = []
        for i, line in enumerate(lines):
            if start <= i < end:
                if offset > 0:  # Shift right
                    new_line = '░' * offset + line[:-offset] if len(line) > offset else '░' * len(line)
                elif offset < 0:  # Shift left
                    new_line = line[-offset:] + '░' * (-offset)
                else:
                    new_line = line
                result.append(new_line)
            else:
                result.append(line)
        return result
    
    def _apply_y_scale(self, lines: List[str], scale: float, start: int, end: int) -> List[str]:
        """Apply vertical scaling (compression/expansion)."""
        # Simplified: for compression, skip some rows; for expansion, duplicate some
        if scale == 1.0:
            return lines
        
        result = lines.copy()
        affected = lines[start:end]
        target_height = int(len(affected) * scale)
        
        if scale < 1.0:  # Compress
            # Sample rows to keep
            step = len(affected) / target_height if target_height > 0 else 1
            new_affected = []
            for i in range(target_height):
                src_idx = int(i * step)
                if src_idx < len(affected):
                    new_affected.append(affected[src_idx])
            
            # Pad with empty rows to maintain line count
            padding = len(affected) - len(new_affected)
            new_affected = ['░' * len(lines[0])] * (padding // 2) + new_affected + ['░' * len(lines[0])] * (padding - padding // 2)
            
            result = result[:start] + new_affected + result[end:]
        
        # Expansion is more complex - skip for now
        
        return result
    
    def render_animated_pose(self, pose_lines: List[str]) -> List[str]:
        """Render a pose with current animation and any overlays applied."""
        # Apply main animation frame
        frame = self.get_current_frame()
        result = self.apply_frame_to_lines(pose_lines, frame)
        
        # Apply overlay animation if active
        if self.overlay_animation:
            overlay_frame = self._get_overlay_frame()
            if overlay_frame:
                result = self.apply_frame_to_lines(result, overlay_frame)
            else:
                # Overlay finished
                self.overlay_animation = None
                self.head_animation_active = False
        
        return result
    
    def _get_overlay_frame(self) -> Optional[AnimationFrame]:
        """Get current frame from overlay animation."""
        if not self.overlay_animation:
            return None
        
        now = time.time()
        elapsed_ms = (now - self.overlay_start_time) * 1000
        
        cumulative_ms = 0
        for frame in self.overlay_animation.frames:
            cumulative_ms += frame.duration_ms
            if elapsed_ms < cumulative_ms:
                return frame
        
        # Overlay finished
        if self.overlay_animation.loop:
            self.overlay_start_time = now
            return self.overlay_animation.frames[0]
        
        return None
    
    def start_transition(self, source_lines: List[str], target_lines: List[str], 
                        transition_type: str = "dissolve", duration_ms: int = 500):
        """Start a transition between two poses."""
        self.transitioning = True
        self.source_pose_lines = source_lines
        self.target_pose_lines = target_lines
        
        if transition_type == "dissolve":
            self.trigger_animation(create_dissolve_transition(duration_ms))
        elif transition_type == "slide_left":
            self.trigger_animation(create_slide_transition("left", 20, duration_ms))
        elif transition_type == "slide_right":
            self.trigger_animation(create_slide_transition("right", 20, duration_ms))
        elif transition_type == "turnaround":
            # Use turnaround for orientation changes
            self.trigger_animation(TURNAROUND_ANIMATIONS.get("front_to_back", create_dissolve_transition(duration_ms)))
    
    def render_transition_frame(self) -> List[str]:
        """Render current transition frame (blend between source and target)."""
        if not self.transitioning:
            return self.target_pose_lines
        
        frame = self.get_current_frame()
        
        if frame.opacity is not None and frame.opacity < 1.0:
            # Dissolve: blend based on opacity
            return self._blend_poses(self.source_pose_lines, self.target_pose_lines, frame.opacity)
        else:
            # Slide or other: apply transform to source, show target underneath
            transformed = self.apply_frame_to_lines(self.source_pose_lines, frame)
            return transformed
    
    def _blend_poses(self, source: List[str], target: List[str], source_opacity: float) -> List[str]:
        """Blend two poses together based on opacity."""
        result = []
        
        # Character "weight" for blending
        char_weight = {' ': 0, '░': 1, '▒': 2, '▓': 3, '█': 4}
        weight_char = {0: ' ', 1: '░', 2: '▒', 3: '▓', 4: '█'}
        
        for i in range(max(len(source), len(target))):
            src_line = source[i] if i < len(source) else ''
            tgt_line = target[i] if i < len(target) else ''
            
            # Pad to same length
            max_len = max(len(src_line), len(tgt_line))
            src_line = src_line.ljust(max_len)
            tgt_line = tgt_line.ljust(max_len)
            
            blended = ''
            for j in range(max_len):
                src_char = src_line[j] if j < len(src_line) else ' '
                tgt_char = tgt_line[j] if j < len(tgt_line) else ' '
                
                # Simple blend: weighted average
                src_w = char_weight.get(src_char, 2)
                tgt_w = char_weight.get(tgt_char, 2)
                
                blended_w = int(src_w * source_opacity + tgt_w * (1 - source_opacity))
                blended_w = max(0, min(4, blended_w))
                
                blended += weight_char.get(blended_w, src_char if source_opacity > 0.5 else tgt_char)
            
            result.append(blended)
        
        return result


# ═══════════════════════════════════════════════════════════════════════════════
#                    POSE-DIALOGUE SCENE SYSTEM
#              Combine poses + animations + dialogue for non-rhythm scenes
# ═══════════════════════════════════════════════════════════════════════════════

@dataclass
class DialogueSceneBeat:
    """A single beat in a pose-animated dialogue scene."""
    speaker: str                      # "BIRDSONG", "FIEND", "SOUND", "PAUSE"
    text: str                         # Dialogue text
    pose: Optional[str] = None        # Pose to show (None = keep current)
    animation: Optional[str] = None   # Reaction animation to trigger
    breathing: Optional[str] = None   # Change breathing rate
    duration_ms: int = 0              # For PAUSE beats
    transition: Optional[str] = None  # Transition type when changing pose


@dataclass  
class DialogueScene:
    """A complete pose-animated dialogue scene."""
    scene_id: str
    context: str                      # Narrative context
    initial_pose: str                 # Starting pose
    initial_breathing: str            # Starting breathing rate
    beats: List[DialogueSceneBeat]
    power_dynamic_threshold: Optional[float] = None  # If set, this is a branched scene
    power_requirement: Optional[str] = None  # "BIRD_DOM", "FIEND_DOM", "CONTESTED", or None
    depth_min: float = 0.0            # Minimum depth to trigger


