def select_dialogue_scene(context: str, power_dynamic: float, depth: float) -> Optional[DialogueScene]:
    """Select an appropriate dialogue scene based on context and state."""
    power_mode = "BIRD_DOM" if power_dynamic < -0.4 else ("FIEND_DOM" if power_dynamic > 0.4 else "CONTESTED")
    
    candidates = []
    for scene_id, scene in DIALOGUE_SCENES.items():
        # Check context match (flexible - check if context keyword is in scene_id or context)
        context_match = (
            context.lower() in scene_id.lower() or 
            context.lower() in scene.context.lower() or
            scene_id.lower() in context.lower()
        )
        if not context_match:
            continue
        
        # Check depth requirement
        if scene.depth_min > depth:
            continue
        
        # Check power requirement (None means any power)
        if scene.power_requirement:
            if scene.power_requirement != power_mode:
                continue
        
        # Weight by how well it matches
        weight = 1.0
        if scene.power_requirement == power_mode:
            weight = 2.0  # Bonus for power match
        
        candidates.append((scene, weight))
    
    if not candidates:
        return None
    
    # Weighted random selection
    total_weight = sum(w for _, w in candidates)
    r = random.random() * total_weight
    cumulative = 0
    for scene, weight in candidates:
        cumulative += weight
        if r <= cumulative:
            return scene
    
    return candidates[0][0] if candidates else None


def get_pose_for_emotion(emotion: str, power_dynamic: float = 0.0) -> str:
    """Get the best pose for a given emotion."""
    best_pose = "face"  # Default
    best_score = 0
    
    for pose_name, pose_data in POSE_EMOTIONAL_MAP.items():
        if emotion in pose_data["emotions"]:
            score = 1
            
            # Bonus for power match
            if power_dynamic < -0.3 and pose_data["power_lean"] == "bird_dom":
                score += 1
            elif power_dynamic > 0.3 and pose_data["power_lean"] == "fiend_dom":
                score += 1
            elif -0.3 <= power_dynamic <= 0.3 and pose_data["power_lean"] == "neutral":
                score += 0.5
            
            if score > best_score:
                best_score = score
                best_pose = pose_name
    
    return best_pose


