def select_power_dilemma(
    mode: str,
    tier: int,
    trust_profile,
    recent_dilemmas: List[str],
    momentum: float,
    composure: float,
) -> Optional[PowerDilemma]:
    """Select an appropriate dilemma based on game state."""
    candidates = []
    
    for dilemma_id, dilemma in POWER_DILEMMAS.items():
        # Skip recently used
        if dilemma_id in recent_dilemmas[-5:]:
            continue
        
        # Check mode requirement
        if dilemma.requires_mode and dilemma.requires_mode != mode:
            continue
        
        # Check tier requirement
        if dilemma.requires_tier and dilemma.requires_tier > tier:
            continue
        
        # Check trust minimum
        total_trust = (
            trust_profile.trust_vulnerability +
            trust_profile.trust_control +
            trust_profile.trust_intensity +
            trust_profile.trust_intimacy
        ) // 4
        
        if total_trust < dilemma.min_trust:
            continue
        
        # Weight by appropriateness
        weight = 1.0
        
        if momentum > 0.5 and dilemma.true_intent == TrueIntent.WANTS_TAMING:
            weight *= 1.5
        if composure > 0.4 and dilemma.true_intent == TrueIntent.WANTS_CONTROL:
            weight *= 1.3
        if composure < 0.3 and dilemma.true_intent == TrueIntent.WANTS_SOFTNESS:
            weight *= 1.4
        if mode == "rough" and dilemma.true_intent == TrueIntent.WANTS_FIRM_NO:
            weight *= 1.5
        if tier >= 2 and dilemma.true_intent == TrueIntent.WANTS_SURRENDER:
            weight *= 1.5
        
        candidates.append((dilemma, weight))
    
    if not candidates:
        return None
    
    # Weighted random selection
    total_weight = sum(w for _, w in candidates)
    r = random.random() * total_weight
    
    cumulative = 0
    for dilemma, weight in candidates:
        cumulative += weight
        if r <= cumulative:
            return dilemma
    
    return candidates[-1][0]


def evaluate_dilemma_choice(
    dilemma: PowerDilemma,
    chosen_key: str,
) -> Tuple[bool, Optional[DilemmaOption], List[Tuple[str, str]]]:
    """Evaluate a choice against the dilemma's true intent."""
    option = None
    for opt in dilemma.options.values():
        if opt.key == chosen_key:
            option = opt
            break
    
    if not option:
        return False, None, []
    
    is_correct = (
        option.assumes_intent == dilemma.true_intent or
        dilemma.true_intent == TrueIntent.AMBIGUOUS
    )
    
    if is_correct:
        response = option.correct_response if option.correct_response else option.incorrect_response
    else:
        response = option.incorrect_response if option.incorrect_response else option.correct_response
    
    return is_correct, option, response


