#                    DEEP STATE DETECTION SYSTEM
# ═══════════════════════════════════════════════════════════════════════════════
#
# Routes dialogue to appropriate NLS_EXCHANGE category based on detected state

def get_state_appropriate_exchange(vibe: 'Vibe', intensity: float, 
                                    recent_performance: str = "neutral") -> List[Tuple]:
    """
    Select exchange category based on detected Birdsong state + performance.
    Returns a full exchange with NLS injection.
    """
    import random
    
    # Detect Birdsong state from game signals
    state = detect_birdsong_state(vibe, intensity, 
                                   recent_misses=getattr(vibe, 'recent_misses', 0))
    
    # Performance can override state
    if recent_performance == "on_fire" and state not in ("melting", "needy"):
        state = random.choice(["melting", "bratty"])  # She's affected
    elif recent_performance == "struggling":
        state = random.choice(["bratty", "rambling"])  # She teases
    
    # Get exchanges for this state
    exchanges = NLS_EXCHANGES.get(state, NLS_EXCHANGES.get("rambling", [[]]))
    if not exchanges:
        return []
    
    exchange = random.choice(exchanges)
    
    # Inject NLS based on state
    result = []
    for item in exchange:
        if isinstance(item, tuple) and len(item) == 2:
            speaker, text = item
            if speaker == "BIRDSONG":
                text = inject_birdsong_nls(text, intensity=intensity, state=state)
            elif speaker == "FIEND":
                # Fiend gets caught more when she's bratty
                caught = state == "bratty" and random.random() < 0.3
                text = inject_fiend_nls(text, caught=caught)
            result.append((speaker, text))
        else:
            result.append(item)  # SILENCE, SOUND, etc.
    
    return result

