# ═══════════════════════════════════════════════════════════════════════════════
#                    READING BIRDSONG - STATE DETECTION
# ═══════════════════════════════════════════════════════════════════════════════

def detect_birdsong_state(vibe: 'Vibe', intensity: float, recent_misses: int = 0) -> str:
    """
    Detect Birdsong's current state from game signals.
    This is what you're learning to READ.
    """
    # High intensity + low misses = she's melting
    if intensity > 75 and recent_misses < 2:
        return "melting"
    
    # High intensity + some struggle = needy
    if intensity > 50 and recent_misses < 4:
        return "needy"
    
    # Low intensity + high verbal from player = she's rambling back
    if intensity < 40 and vibe.verbal > vibe.silent:
        return "rambling"
    
    # Mid intensity + player being physical = she's bratty (testing)
    if 30 < intensity < 60 and vibe.physical > vibe.verbal:
        return "bratty"
    
    # Very low intensity OR after climax = quiet (vulnerable)
    if intensity < 20 or vibe.climax_reached:
        return "quiet"
    
    # Default to rambling (she always has something to say)
    return "rambling"

def get_optimal_tool(birdsong_state: str) -> Tuple[str, float]:
    """Get the most Fiend-like tool for this state"""
    scores = FIEND_PLAYBOOK.get(birdsong_state, {})
    if not scores:
        return "observe", 0.5
    
    best_tool = max(scores, key=scores.get)
    return best_tool, scores[best_tool]

def get_gambits_for_state(birdsong_state: str, count: int = 3) -> List[Tuple[str, str, float]]:
    """
    Get gambits sorted by Fiend-optimality for current state.
    Returns: [(gambit_id, tool, score), ...]
    """
    scores = FIEND_PLAYBOOK.get(birdsong_state, {})
    
    result = []
    for gambit_id, gambit in GAMBIT_CATALOG.items():
        tool = gambit.get("tool", "observe")
        tool_score = scores.get(tool, 0.5)
        result.append((gambit_id, tool, tool_score))
    
    # Sort by score descending
    result.sort(key=lambda x: x[2], reverse=True)
    
    # Add slight randomness to top choices for variety
    top = result[:count + 2]
    random.shuffle(top)
    
    return top[:count]

def get_contextualized_choices(profile: 'PlayerProfile', context: str, count: int = 4,
                               birdsong_state: str = None, composure: float = None,
                               cascade: 'DialogueCascade' = None) -> List[str]:
    """
    Get gambit choices based on current context, player profile, AND actual birdsong state.
    Returns list of gambit_ids suitable for the current situation.
    
    If birdsong_state is provided, use it directly for optimal selection.
    Otherwise, infer from context (legacy behavior).
    
    If cascade is provided, uses trajectory to weight choices.
    
    Context maps to birdsong states (fallback):
      - "gentle_start", "tender" → quiet/melting
      - "building", "teasing" → rambling/bratty  
      - "intense", "dominant" → needy/bratty
      - "romantic" → melting/quiet
    """
    # Use actual detected state if provided, otherwise infer
    if birdsong_state:
        state = birdsong_state
    else:
        # Fallback: infer from context
        context_to_state = {
            "gentle_start": "quiet",
            "tender": "melting",
            "building": "rambling",
            "teasing": "bratty",
            "intense": "needy",
            "dominant": "bratty",
            "romantic": "melting",
        }
        state = context_to_state.get(context, "rambling")
    
    # Get gambits optimal for this state (uses FIEND_PLAYBOOK scoring)
    gambits = get_gambits_for_state(state, count + 4)  # Get more for variety
    
    # Extract just the gambit_ids, preserving score order (best first)
    gambit_ids = [g[0] for g in gambits]
    
    # ═══════════════════════════════════════════════════════════════════════
    # CASCADE-AWARE WEIGHTING - Trajectory influences choice availability
    # ═══════════════════════════════════════════════════════════════════════
    if cascade:
        traj = cascade.trajectory
        
        # Build weight adjustments based on trajectory
        weighted_gambits = []
        for gid in gambit_ids:
            gambit_data = GAMBIT_CATALOG.get(gid, {})
            tags = gambit_data.get("tags", [])
            weight = 1.0
            
            # Emotional direction weighting
            if traj.emotional_direction > 0.3:
                if "escalate" in tags or "aggressive" in tags:
                    weight *= 1.4
                if "gentle" in tags or "retreat" in tags:
                    weight *= 0.6
            elif traj.emotional_direction < -0.3:
                if "gentle" in tags or "ground" in tags:
                    weight *= 1.4
                if "escalate" in tags:
                    weight *= 0.6
            
            # Power direction weighting
            if traj.power_direction > 0.3:  # Fiend dominant
                if "command" in tags or "dominant" in tags:
                    weight *= 1.3
            elif traj.power_direction < -0.3:  # Bird dominant
                if "tease" in tags or "playful" in tags:
                    weight *= 1.3
            
            # Direction locked - stronger bias
            if traj.direction_locked:
                if traj.consecutive_advances >= 5:
                    if "intense" in tags or "climax" in tags:
                        weight *= 1.5
                elif traj.consecutive_retreats >= 5:
                    if "gentle" in tags or "pause" in tags:
                        weight *= 1.5
            
            weighted_gambits.append((gid, weight))
        
        # Sort by weight (highest first)
        weighted_gambits.sort(key=lambda x: x[1], reverse=True)
        gambit_ids = [g[0] for g in weighted_gambits]
    
    # Composure affects what's appropriate
    # Low composure (< 0.3) → avoid aggressive gambits
    # High composure (> 0.7) → can use more challenging gambits
    if composure is not None:
        filtered = []
        for gid in gambit_ids:
            gambit_data = GAMBIT_CATALOG.get(gid, {})
            tags = gambit_data.get("tags", [])
            
            # Low composure: filter out aggressive/escalating choices
            if composure < 0.3 and ("escalate" in tags or "aggressive" in tags):
                continue
            # High composure: can include everything
            filtered.append(gid)
            
            if len(filtered) >= count + 2:
                break
        gambit_ids = filtered if filtered else gambit_ids
    
    # Use seeded shuffle if cascade available (deterministic)
    top_half = gambit_ids[:count]
    if cascade:
        # Seeded shuffle for reproducibility
        seed = cascade.get_cascade_seed()
        rng = random.Random(seed)
        rng.shuffle(top_half)
    else:
        random.shuffle(top_half)
    
    return top_half[:count]

# ═══════════════════════════════════════════════════════════════════════════════
#                    MASTERY TRACKING
# ═══════════════════════════════════════════════════════════════════════════════
#
# The profile tracks your MASTERY of Fiend, not your interpretation.
# - How often do you pick the Fiend-optimal choice?
# - Do you recognize when she's rambling vs. when she needs words?
# - Can you read the moment?

@dataclass 
class FiendMastery:
    """Track mastery of each tool and state-reading"""
    
    # Tool mastery: how well you use each tool in the RIGHT moments
    observe_correct: int = 0
    observe_total: int = 0
    command_correct: int = 0
    command_total: int = 0
    escalate_correct: int = 0
    escalate_total: int = 0
    ground_correct: int = 0
    ground_total: int = 0
    tease_correct: int = 0
    tease_total: int = 0
    recall_correct: int = 0
    recall_total: int = 0
    
    # State reading: how well you identify her state
    rambling_reads: int = 0
    rambling_correct: int = 0
    bratty_reads: int = 0
    bratty_correct: int = 0
    melting_reads: int = 0
    melting_correct: int = 0
    needy_reads: int = 0
    needy_correct: int = 0
    quiet_reads: int = 0
    quiet_correct: int = 0
    
    def record_choice(self, tool: str, birdsong_state: str, was_optimal: bool):
        """Record a gambit choice and whether it was the Fiend move"""
        # Track tool usage
        tool_total = f"{tool}_total"
        tool_correct = f"{tool}_correct"
        if hasattr(self, tool_total):
            setattr(self, tool_total, getattr(self, tool_total) + 1)
            if was_optimal:
                setattr(self, tool_correct, getattr(self, tool_correct) + 1)
        
        # Track state reading
        state_reads = f"{birdsong_state}_reads"
        state_correct = f"{birdsong_state}_correct"
        if hasattr(self, state_reads):
            setattr(self, state_reads, getattr(self, state_reads) + 1)
            if was_optimal:
                setattr(self, state_correct, getattr(self, state_correct) + 1)
    
    def get_tool_mastery(self, tool: str) -> float:
        """Get mastery percentage for a tool (0-1)"""
        total = getattr(self, f"{tool}_total", 0)
        correct = getattr(self, f"{tool}_correct", 0)
        if total == 0:
            return 0.5  # Unknown
        return correct / total
    
    def get_state_mastery(self, state: str) -> float:
        """Get mastery percentage for reading a state (0-1)"""
        reads = getattr(self, f"{state}_reads", 0)
        correct = getattr(self, f"{state}_correct", 0)
        if reads == 0:
            return 0.5  # Unknown
        return correct / reads
    
    def get_overall_mastery(self) -> float:
        """Get overall Fiend mastery percentage"""
        total_correct = sum(getattr(self, f"{t}_correct", 0) for t in FIEND_TOOLS)
        total_attempts = sum(getattr(self, f"{t}_total", 0) for t in FIEND_TOOLS)
        if total_attempts == 0:
            return 0.5
        return total_correct / total_attempts
    
    def get_weakest_area(self) -> Tuple[str, float]:
        """Get the area you need most practice in"""
        tool_scores = [(t, self.get_tool_mastery(t)) for t in FIEND_TOOLS]
        state_scores = [(s, self.get_state_mastery(s)) for s in BIRDSONG_STATES]
        
        all_scores = tool_scores + state_scores
        # Filter out unknowns (0.5 with no attempts)
        known = [(name, score) for name, score in all_scores 
                 if getattr(self, f"{name}_total", 0) > 0 or getattr(self, f"{name}_reads", 0) > 0]
        
        if not known:
            return "observe", 0.5
        
        return min(known, key=lambda x: x[1])
    
    def to_dict(self) -> dict:
        return {k: v for k, v in self.__dict__.items()}
    
    @classmethod
    def from_dict(cls, data: dict) -> 'FiendMastery':
        mastery = cls()
        for k, v in data.items():
            if hasattr(mastery, k):
                setattr(mastery, k, v)
        return mastery

