# ═══════════════════════════════════════════════════════════════════════════════
#                         CONTEXT DETECTION
# ═══════════════════════════════════════════════════════════════════════════════

def detect_fiend_mode(vibe: 'Vibe', current_mode: str) -> str:
    """Detect current Fiend mode from game state"""
    # Based on game mode and player style
    if current_mode == "rough":
        if vibe.physical > vibe.verbal:
            return "hungry"
        return "scary"
    elif current_mode == "gentle":
        if vibe.silent > vibe.verbal:
            return "silent"
        return "soft"
    else:  # steady
        if vibe.stammers > 2:
            return "teasing"
        if vibe.verbal > vibe.physical:
            return "teasing"
        return random.choice(["soft", "teasing", "hungry"])

def detect_birdsong_mode(vibe: 'Vibe', intensity: float, recent_dialogue: str = "") -> str:
    """Detect current Birdsong mode from game state"""
    # Based on intensity and recent interactions
    if intensity > 80:
        return "melting"
    elif intensity > 60:
        if vibe.stammers > vibe.verbal:
            return "quiet"
        return "needy"
    elif intensity > 30:
        if vibe.verbal > vibe.physical:
            return "ramble"
        return "bratty"
    else:
        return "bratty" if random.random() > 0.5 else "ramble"

def get_optimal_gambits(fiend_mode: str, bird_mode: str, count: int = 4) -> List[Tuple[str, float]]:
    """Get gambits sorted by optimality for current context"""
    context = (fiend_mode, bird_mode)
    
    scored = []
    for gambit_id, gambit in GAMBIT_CATALOG.items():
        optimal_contexts = gambit.get("optimal_contexts", {})
        
        # Get score for this exact context, or interpolate
        if context in optimal_contexts:
            score = optimal_contexts[context]
        else:
            # Check partial matches
            fiend_matches = [s for (f, b), s in optimal_contexts.items() if f == fiend_mode]
            bird_matches = [s for (f, b), s in optimal_contexts.items() if b == bird_mode]
            
            if fiend_matches and bird_matches:
                score = (max(fiend_matches) + max(bird_matches)) / 2 * 0.7
            elif fiend_matches:
                score = max(fiend_matches) * 0.5
            elif bird_matches:
                score = max(bird_matches) * 0.5
            else:
                score = 0.3  # Unknown context
        
        # Add slight randomness for variety
        score += random.uniform(-0.05, 0.05)
        scored.append((gambit_id, score))
    
    scored.sort(key=lambda x: x[1], reverse=True)
    return scored[:count]

    scr.getch()


# ═══════════════════════════════════════════════════════════════════════════════
#                    ACHIEVEMENT SYSTEM: THE LIVING RECORD
# ═══════════════════════════════════════════════════════════════════════════════
#
# Not just "do X times" - each achievement is a MOMENT discovered, a branch
# explored, a micro-event witnessed. Tiered by rarity, unlocking real content.
#
# Categories:
#   MOMENTS     - Specific dialogue/event triggers you can force
#   MASTERY     - Reading her states, using tools optimally  
#   DISCOVERY   - Finding hidden branches, rare events
#   DEVOTION    - Cross-session dedication, patterns over time
#   STYLE       - Developing YOUR Fiend identity
#
# Tiers: COMMON → UNCOMMON → RARE → LEGENDARY → MYTHIC
# Each tier harder to achieve, better rewards

@dataclass
class Achievement:
    """A single achievement definition."""
    id: str
    name: str                           # Display name
    description: str                    # Flavor text (often Birdsong voice)
    hint: str                           # How to unlock (can be cryptic)
    tier: str                           # common/uncommon/rare/legendary/mythic
    category: str                       # moments/mastery/discovery/devotion/style
    
    # Unlock conditions (check functions set these)
    stat_key: Optional[str] = None      # Simple stat >= threshold
    stat_threshold: int = 1
    check_func: Optional[str] = None    # Name of custom check function
    
    # Rewards
    reward_type: Optional[str] = None   # hud_skin/dialogue_pack/pose_variant/title/border
    reward_id: Optional[str] = None     # Specific reward to unlock
    reward_description: str = ""        # What you get
    
    # Tracking
    hidden: bool = False                # Don't show until unlocked
    secret: bool = False                # Don't show hint either
    prerequisite: Optional[str] = None  # Must have this achievement first


