# ═══════════════════════════════════════════════════════════════════════════════
#                    ACHIEVEMENT TRACKING STATE
# ═══════════════════════════════════════════════════════════════════════════════

@dataclass
class AchievementProgress:
    """Tracks progress toward all achievements."""
    # Unlocked achievements (by id)
    unlocked: List[str] = field(default_factory=list)
    unlock_dates: Dict[str, str] = field(default_factory=dict)
    
    # Counters for stat-based achievements
    mwehh_heard: int = 0
    mwehh_states_seen: int = 0
    mwehh_states_list: List[str] = field(default_factory=list)
    baka_heard: int = 0
    baka_cascade_max: int = 0
    stare_breaks: int = 0
    good_girl_said: int = 0
    good_girl_perfect: int = 0
    name_loops_completed: int = 0
    
    # State reading
    rambling_reads: int = 0
    bratty_handled: int = 0
    melting_caught: int = 0
    quiet_handled: int = 0
    
    # Discovery
    slips_witnessed: int = 0
    wrong_holes_witnessed: int = 0
    escapes_witnessed: int = 0
    love_bunny_entries: int = 0
    love_bunny_completions: int = 0
    starving_entries: int = 0
    edges_completed: int = 0
    transcendence_reached: int = 0
    transcendence_completions: int = 0
    
    # Session tracking
    sessions_completed: int = 0
    total_minutes: int = 0
    total_climaxes: int = 0
    max_combo_ever: int = 0
    
    # Style tracking (mirrors TrustProfile but for achievements)
    style_verbal: int = 0
    style_physical: int = 0
    style_silent: int = 0
    tempo_patient: int = 0
    tempo_eager: int = 0
    tempo_aggressive: int = 0
    
    # Special event flags
    fiend_baka_used: bool = False
    uwu_incident: bool = False
    owo_response: bool = False
    pure_silence_break: bool = False
    yours_admission: bool = False
    genuine_please: bool = False
    i_need_moment: bool = False
    name_moment: bool = False
    outhouse_discovered: bool = False
    hump_dog_unlocked: bool = False
    triple_mwehh_session: bool = False
    mutual_silence_achieved: bool = False
    full_spectrum_session: bool = False
    perfect_session_achieved: bool = False
    
    # Per-session tracking (reset each session)
    session_edges: int = 0
    session_mwehhs: int = 0
    session_modes_entered: List[str] = field(default_factory=list)
    session_misses: int = 0
    
    def to_dict(self) -> dict:
        """Serialize for saving."""
        data = {}
        for k, v in self.__dict__.items():
            if not k.startswith('session_'):  # Don't save per-session data
                data[k] = v
        return data
    
    @classmethod
    def from_dict(cls, data: dict) -> 'AchievementProgress':
        """Deserialize from saved data."""
        progress = cls()
        for k, v in data.items():
            if hasattr(progress, k):
                setattr(progress, k, v)
        return progress
    
    def reset_session(self):
        """Reset per-session tracking."""
        self.session_edges = 0
        self.session_mwehhs = 0
        self.session_modes_entered = []
        self.session_misses = 0


# ═══════════════════════════════════════════════════════════════════════════════
#                    ACHIEVEMENT CHECK FUNCTIONS
# ═══════════════════════════════════════════════════════════════════════════════

def check_achievement_stat(progress: AchievementProgress, achievement: Achievement) -> bool:
    """Check if a stat-based achievement is unlocked."""
    if achievement.stat_key:
        current = getattr(progress, achievement.stat_key, 0)
        return current >= achievement.stat_threshold
    return False


def check_triple_mwehh(progress: AchievementProgress) -> bool:
    """Check if player triggered 3 mwehhs in one exchange."""
    return progress.triple_mwehh_session


def check_baka_cascade(progress: AchievementProgress) -> bool:
    """Check if player triggered a full baka cascade."""
    return progress.baka_cascade_max >= 3


def check_fiend_baka(progress: AchievementProgress) -> bool:
    """Check if Fiend used baka response."""
    return progress.fiend_baka_used


def check_pure_silence_break(progress: AchievementProgress) -> bool:
    """Check if player broke her with silence alone."""
    return progress.pure_silence_break


def check_yours_admission(progress: AchievementProgress) -> bool:
    """Check if 'yours' admission was triggered."""
    return progress.yours_admission


def check_genuine_please(progress: AchievementProgress) -> bool:
    """Check if genuine 'please' was triggered."""
    return progress.genuine_please


def check_i_need_moment(progress: AchievementProgress) -> bool:
    """Check if 'I need—' moment was triggered."""
    return progress.i_need_moment


def check_name_moment(progress: AchievementProgress) -> bool:
    """Check if intimate name moment occurred."""
    return progress.name_moment


def check_outhouse_discovered(progress: AchievementProgress) -> bool:
    """Check if outhouse scene was discovered."""
    return progress.outhouse_discovered


def check_hump_dog_unlocked(progress: AchievementProgress) -> bool:
    """Check if hump dog mode was unlocked."""
    return progress.hump_dog_unlocked


def check_edge_master(progress: AchievementProgress) -> bool:
    """Check if player edged 5 times in one session."""
    return progress.session_edges >= 5


def check_observe_mastery(progress: AchievementProgress, mastery: 'FiendMastery') -> bool:
    """Check observe tool mastery."""
    if mastery.observe_total >= 20:
        return mastery.get_tool_mastery('observe') >= 0.85
    return False


def check_command_mastery(progress: AchievementProgress, mastery: 'FiendMastery') -> bool:
    """Check command tool mastery."""
    if mastery.command_total >= 20:
        return mastery.get_tool_mastery('command') >= 0.85
    return False


def check_ground_mastery(progress: AchievementProgress, mastery: 'FiendMastery') -> bool:
    """Check ground tool mastery."""
    if mastery.ground_total >= 15:
        return mastery.get_tool_mastery('ground') >= 0.85
    return False


def check_tease_mastery(progress: AchievementProgress, mastery: 'FiendMastery') -> bool:
    """Check tease tool mastery."""
    if mastery.tease_total >= 20:
        return mastery.get_tool_mastery('tease') >= 0.85
    return False


def check_all_tool_mastery(progress: AchievementProgress, mastery: 'FiendMastery') -> bool:
    """Check if all tools are mastered."""
    tools = ['observe', 'command', 'escalate', 'ground', 'tease', 'recall']
    for tool in tools:
        total = getattr(mastery, f"{tool}_total", 0)
        if total < 15 or mastery.get_tool_mastery(tool) < 0.80:
            return False
    return True


def check_state_mastery(progress: AchievementProgress, mastery: 'FiendMastery') -> bool:
    """Check if all states are being read at 80%+ accuracy."""
    states = ['rambling', 'bratty', 'melting', 'needy', 'quiet']
    for state in states:
        if mastery.get_state_mastery(state) < 0.80:
            return False
    return True


def check_balanced_fiend(progress: AchievementProgress) -> bool:
    """Check if player has 50+ in all style/tempo categories."""
    return (progress.style_verbal >= 50 and 
            progress.style_physical >= 50 and 
            progress.style_silent >= 50 and
            progress.tempo_patient >= 50 and 
            progress.tempo_eager >= 50 and 
            progress.tempo_aggressive >= 50)


def check_identity_formed(progress: AchievementProgress) -> bool:
    """Check if player has developed distinct style over 25+ sessions."""
    if progress.sessions_completed < 25:
        return False
    # Check for clear style dominance
    styles = [progress.style_verbal, progress.style_physical, progress.style_silent]
    if max(styles) < 80:
        return False
    # Check for clear tempo preference
    tempos = [progress.tempo_patient, progress.tempo_eager, progress.tempo_aggressive]
    if max(tempos) < 60:
        return False
    return True


def check_uwu_incident(progress: AchievementProgress) -> bool:
    """Check if the uwu incident occurred."""
    return progress.uwu_incident


def check_owo_response(progress: AchievementProgress) -> bool:
    """Check if owo response was used."""
    return progress.owo_response


def check_mutual_silence(progress: AchievementProgress) -> bool:
    """Check if mutual silence moment occurred."""
    return progress.mutual_silence_achieved


def check_full_spectrum(progress: AchievementProgress) -> bool:
    """Check if all modes were entered in one session."""
    required_modes = {'love_bunny', 'hump_dog', 'starving', 'edge'}
    return required_modes.issubset(set(progress.session_modes_entered))


def check_perfect_session(progress: AchievementProgress) -> bool:
    """Check if a perfect session (no misses) was achieved."""
    return progress.perfect_session_achieved


def check_completion(progress: AchievementProgress) -> bool:
    """Check if all non-mythic achievements are unlocked."""
    non_mythic = [a for a in ACHIEVEMENTS.values() if a.tier != 'mythic' and a.id != 'completion']
    return all(a.id in progress.unlocked for a in non_mythic)


