#                    ACHIEVEMENT SYSTEM CORE
# ═══════════════════════════════════════════════════════════════════════════════

class AchievementSystem:
    """Manages achievement checking, unlocking, and rewards."""
    
    def __init__(self, progress: AchievementProgress, mastery: 'FiendMastery' = None):
        self.progress = progress
        self.mastery = mastery or FiendMastery()
        self.pending_unlocks: List[Achievement] = []
        self.active_rewards: Dict[str, Any] = {}
        self._hydrate_active_rewards()

    def _hydrate_active_rewards(self):
        """Rebuild active reward hooks from saved achievements on boot."""
        try:
            for ach_id in list(getattr(self.progress, "unlocked", []) or []):
                ach = ACHIEVEMENTS.get(ach_id)
                if ach and ach.reward_type and ach.reward_id:
                    self.active_rewards[ach.reward_id] = {
                        'type': ach.reward_type,
                        'from_achievement': ach.id,
                        'description': ach.reward_description,
                    }
        except Exception:
            pass
    
    def check_all(self) -> List[Achievement]:
        """Check all achievements and return newly unlocked ones."""
        newly_unlocked = []
        
        for ach_id, ach in ACHIEVEMENTS.items():
            # Skip if already unlocked
            if ach_id in self.progress.unlocked:
                continue
            
            # Check prerequisite
            if ach.prerequisite and ach.prerequisite not in self.progress.unlocked:
                continue
            
            # Check unlock condition
            unlocked = False
            
            if ach.stat_key:
                # Stat-based check
                unlocked = check_achievement_stat(self.progress, ach)
            elif ach.check_func:
                # Custom check function
                check_fn = globals().get(ach.check_func)
                if check_fn:
                    # Some checks need mastery
                    if 'mastery' in ach.check_func:
                        unlocked = check_fn(self.progress, self.mastery)
                    else:
                        unlocked = check_fn(self.progress)
            
            if unlocked:
                self._unlock(ach)
                newly_unlocked.append(ach)
        
        return newly_unlocked
    
    def _unlock(self, achievement: Achievement):
        """Unlock an achievement and apply rewards."""
        from datetime import datetime
        
        self.progress.unlocked.append(achievement.id)
        self.progress.unlock_dates[achievement.id] = datetime.now().isoformat()
        
        # 🎵 ACHIEVEMENT SOUND 🎵
        music_achievement()
        
        # Apply reward
        if achievement.reward_type and achievement.reward_id:
            self.active_rewards[achievement.reward_id] = {
                'type': achievement.reward_type,
                'from_achievement': achievement.id,
                'description': achievement.reward_description,
            }
        
        self.pending_unlocks.append(achievement)
    
    def get_pending_unlock_display(self) -> Optional[Tuple[str, List[str]]]:
        """Get the next pending unlock for display. Returns (title, lines)."""
        if not self.pending_unlocks:
            return None
        
        ach = self.pending_unlocks.pop(0)
        
        # Build display
        tier_symbols = {
            'common': '●',
            'uncommon': '◆',
            'rare': '★',
            'legendary': '✦',
            'mythic': '✧',
        }
        tier_colors = {
            'common': 'white',
            'uncommon': 'green',
            'rare': 'blue',
            'legendary': 'purple',
            'mythic': 'gold',
        }
        
        symbol = tier_symbols.get(ach.tier, '●')
        
        lines = [
            f"",
            f"  {symbol} {ach.name} {symbol}",
            f"",
            f"  \"{ach.description}\"",
            f"",
        ]
        
        if ach.reward_description:
            lines.append(f"  Reward: {ach.reward_description}")
        
        return (f"ACHIEVEMENT UNLOCKED ({ach.tier.upper()})", lines)
    
    def has_reward(self, reward_id: str) -> bool:
        """Check if a specific reward is unlocked."""
        return reward_id in self.active_rewards

    def get_unlocked_rewards(self) -> Dict[str, Any]:
        """Return unlocked reward metadata, including rewards restored from save."""
        self._hydrate_active_rewards()
        return dict(self.active_rewards)
    
    def get_unlocked_count(self) -> Tuple[int, int]:
        """Get (unlocked, total) achievement count."""
        visible = [a for a in ACHIEVEMENTS.values() if not a.secret]
        unlocked_visible = [a for a in visible if a.id in self.progress.unlocked]
        return len(unlocked_visible), len(visible)
    
    def get_tier_counts(self) -> Dict[str, Tuple[int, int]]:
        """Get (unlocked, total) for each tier."""
        counts = {}
        for tier in ['common', 'uncommon', 'rare', 'legendary', 'mythic']:
            tier_achs = [a for a in ACHIEVEMENTS.values() if a.tier == tier and not a.secret]
            unlocked = [a for a in tier_achs if a.id in self.progress.unlocked]
            counts[tier] = (len(unlocked), len(tier_achs))
        return counts
    
    def get_category_list(self, category: str) -> List[Tuple[Achievement, bool]]:
        """Get achievements in a category with unlock status."""
        result = []
        for ach in ACHIEVEMENTS.values():
            if ach.category != category:
                continue
            if ach.secret and ach.id not in self.progress.unlocked:
                continue  # Don't show secret achievements until unlocked
            if ach.hidden and ach.id not in self.progress.unlocked:
                # Show as "???" 
                hidden_ach = Achievement(
                    id=ach.id,
                    name="???",
                    description="This achievement is hidden.",
                    hint="???",
                    tier=ach.tier,
                    category=ach.category,
                    hidden=True,
                )
                result.append((hidden_ach, False))
            else:
                result.append((ach, ach.id in self.progress.unlocked))
        return result


