def _progression_reward_counts(progress: AchievementProgress) -> Tuple[Dict[str, int], List[Dict[str, str]]]:
    """Summarize unlocked achievement reward hooks without gating base systems."""
    counts: Dict[str, int] = {}
    rewards: List[Dict[str, str]] = []
    try:
        for ach_id in list(getattr(progress, "unlocked", []) or []):
            ach = ACHIEVEMENTS.get(ach_id)
            if not ach or not ach.reward_type or not ach.reward_id:
                continue
            counts[ach.reward_type] = counts.get(ach.reward_type, 0) + 1
            rewards.append({
                "achievement": ach.id,
                "reward_id": ach.reward_id,
                "reward_type": ach.reward_type,
                "summary": ach.reward_description or ach.name,
            })
    except Exception:
        pass
    return counts, rewards


def build_progression_reward_state(profile: Any, achievement_system: Optional[AchievementSystem] = None) -> Dict[str, Any]:
    """
    Additive progression state.

    The baseline game stays complete. Levels and achievements only increase
    fidelity, specificity, reward density, and runtime responsiveness.
    """
    try:
        level = max(1, int(getattr(profile, "player_level", 1) or 1))
    except Exception:
        level = 1
    progress = getattr(profile, "achievement_progress", AchievementProgress())
    reward_counts, achievement_rewards = _progression_reward_counts(progress)

    level_rewards = [tier for tier in LEVEL_REWARD_TIERS if level >= int(tier.get("level", 1))]
    effects: Dict[str, float] = {
        "dialogue_density_bonus": 0.0,
        "dialogue_extra_barks": 0.0,
        "figure_response_level": 0.0,
        "frisson_reward_tier": 0.0,
        "lightmap_sync_bonus": 0.0,
        "xp_bonus": 0.0,
        "failure_xp_bonus": 0.0,
    }
    for tier in level_rewards:
        for key, val in dict(tier.get("effects") or {}).items():
            try:
                effects[key] = float(effects.get(key, 0.0)) + float(val)
            except Exception:
                pass

    dialogue_reward_count = (
        int(reward_counts.get("dialogue_pack", 0))
        + int(reward_counts.get("dialogue_branch", 0))
        + int(reward_counts.get("dialogue_variant", 0))
    )
    pose_reward_count = int(reward_counts.get("pose_variant", 0))
    mechanic_reward_count = int(reward_counts.get("mechanic", 0))
    hud_reward_count = int(reward_counts.get("hud_element", 0)) + int(reward_counts.get("hud_skin", 0))

    effects["dialogue_density_bonus"] += min(0.12, 0.012 * dialogue_reward_count)
    effects["figure_response_level"] += min(2.0, pose_reward_count // 2)
    effects["frisson_reward_tier"] += 1.0 if any(r["reward_id"] in ("combo_flame", "title_relentless", "skin_transcendent") for r in achievement_rewards) else 0.0
    effects["xp_bonus"] += min(0.10, 0.01 * mechanic_reward_count + 0.005 * hud_reward_count)
    effects["failure_xp_bonus"] += 0.04 if any(r["reward_id"] in ("wrong_hole_tree", "escape_hunt") for r in achievement_rewards) else 0.0

    active_reward_ids = set()
    if achievement_system is not None:
        try:
            active_reward_ids.update(achievement_system.get_unlocked_rewards().keys())
        except Exception:
            pass
    active_reward_ids.update(r["reward_id"] for r in achievement_rewards)
    level_visible_unlocks: List[str] = []
    for tier in level_rewards:
        try:
            level_visible_unlocks.extend(str(x) for x in (tier.get("visible_unlocks", []) or []))
        except Exception:
            pass

    algorithm_tier = "base"
    if level >= 2 or dialogue_reward_count >= 2:
        algorithm_tier = "callback_memory"
    if level >= 5 or dialogue_reward_count >= 5:
        algorithm_tier = "glint"
    if level >= 9 or dialogue_reward_count >= 9:
        algorithm_tier = "high_resonance"
    if level >= 12 or dialogue_reward_count >= 12:
        algorithm_tier = "authored_blend"

    return {
        "level": level,
        "level_reward_ids": [str(tier.get("id", "")) for tier in level_rewards],
        "level_reward_summaries": [str(tier.get("summary", "")) for tier in level_rewards],
        "level_reward_details": [
            {
                "level": int(tier.get("level", 1)),
                "id": str(tier.get("id", "")),
                "summary": str(tier.get("summary", "")),
                "effects": dict(tier.get("effects") or {}),
                "visible_unlocks": list(tier.get("visible_unlocks", []) or []),
            }
            for tier in level_rewards
        ],
        "level_visible_unlocks": level_visible_unlocks,
        "reward_lightmap_defs": dict(REWARD_LIGHTMAP_DEFS),
        "reward_lightmap_audit": build_reward_lightmap_audit(),
        "achievement_reward_count": len(achievement_rewards),
        "achievement_reward_ids": sorted(active_reward_ids),
        "reward_type_counts": reward_counts,
        "dialogue_algorithm_tier": algorithm_tier,
        "dialogue_density_bonus": max(0.0, min(0.28, float(effects["dialogue_density_bonus"]))),
        "dialogue_extra_barks": int(max(0, min(1, int(effects["dialogue_extra_barks"])))),
        "figure_response_level": int(max(0, min(3, int(effects["figure_response_level"])))),
        "frisson_reward_tier": int(max(0, min(3, int(effects["frisson_reward_tier"])))),
        "lightmap_sync_bonus": int(max(0, min(2, int(effects["lightmap_sync_bonus"])))),
        "xp_bonus": max(0.0, min(0.20, float(effects["xp_bonus"]))),
        "failure_xp_bonus": max(0.0, min(0.15, float(effects["failure_xp_bonus"]))),
        "baseline_complete": True,
    }


def describe_progression_state(state: Dict[str, Any], limit: int = 3) -> List[str]:
    """Short player-facing summaries for result screens/build notes."""
    lines: List[str] = []
    try:
        tier = str(state.get("dialogue_algorithm_tier", "base")).replace("_", " ").title()
        lines.append(f"Dialogue fidelity: {tier}")
        frisson = int(state.get("frisson_reward_tier", 0) or 0)
        light = int(state.get("lightmap_sync_bonus", 0) or 0)
        fig = int(state.get("figure_response_level", 0) or 0)
        if frisson or light or fig:
            lines.append(f"Reward layer: lightmap +{light}, figure +{fig}, frisson {frisson}")
        reward_count = int(state.get("achievement_reward_count", 0) or 0)
        if reward_count:
            lines.append(f"Achievement hooks active: {reward_count}")
        visible = list(state.get("level_visible_unlocks", []) or [])
        for item in visible[:2]:
            if item:
                lines.append(str(item))
    except Exception:
        pass
    return lines[:max(1, int(limit or 3))]


def describe_progression_delta(
    previous: Dict[str, Any],
    current: Dict[str, Any],
    newly_unlocked: List[Achievement],
    leveled_up: bool,
    limit: int = 4,
) -> List[str]:
    """Summarize what changed this session, keeping it compact."""
    lines: List[str] = []
    try:
        if leveled_up:
            lvl = int(current.get("level", 1) or 1)
            summaries = list(current.get("level_reward_summaries", []) or [])
            summary = summaries[-1] if summaries else "Fidelity layer expanded."
            lines.append(f"Level {lvl}: {summary}")
        old_algo = str(previous.get("dialogue_algorithm_tier", "base"))
        new_algo = str(current.get("dialogue_algorithm_tier", "base"))
        if new_algo != old_algo:
            lines.append(f"Dialogue engine: {new_algo.replace('_', ' ')}")
        old_light = int(previous.get("lightmap_sync_bonus", 0) or 0)
        new_light = int(current.get("lightmap_sync_bonus", 0) or 0)
        if new_light > old_light:
            lines.append("Lightmap rewards respond more deeply to lock-in.")
        for ach in list(newly_unlocked or [])[:2]:
            if ach.reward_description:
                lines.append(f"Achievement reward: {ach.reward_description}")
    except Exception:
        pass
    return lines[:max(1, int(limit or 4))]


def on_dialogue_line(progress: AchievementProgress, speaker: str, text: str, state: str = ""):
    """Call this when a dialogue line is displayed."""
    text_lower = text.lower()
    
    # Track mwehh
    if 'mwehh' in text_lower or 'mwehhh' in text_lower:
        progress.mwehh_heard += 1
        progress.session_mwehhs += 1
        if progress.session_mwehhs >= 3:
            progress.triple_mwehh_session = True
        if state and state not in progress.mwehh_states_list:
            progress.mwehh_states_list.append(state)
            progress.mwehh_states_seen = len(progress.mwehh_states_list)
    
    # Track baka
    if 'baka' in text_lower:
        progress.baka_heard += 1
    
    # Track special moments
    if speaker == "BIRDSONG":
        if '...yours' in text_lower or "i'm yours" in text_lower:
            progress.yours_admission = True
        if '...please' in text_lower and 'don\'t' not in text_lower:
            progress.genuine_please = True
        if 'i need—' in text_lower or 'i need you' in text_lower:
            progress.i_need_moment = True
    
    if speaker == "FIEND":
        if 'good girl' in text_lower:
            progress.good_girl_said += 1
        if '...baka' in text_lower:
            progress.fiend_baka_used = True
        if 'uwu' in text_lower:
            progress.uwu_incident = True
        if 'owo' in text_lower:
            progress.owo_response = True


def on_silence_break(progress: AchievementProgress, silence_duration: float, no_dialogue: bool):
    """Call when silence breaks her composure."""
    progress.stare_breaks += 1
    if no_dialogue and silence_duration >= 3.0:
        progress.pure_silence_break = True


def on_baka_cascade(progress: AchievementProgress, cascade_count: int):
    """Call when a baka cascade occurs."""
    if cascade_count > progress.baka_cascade_max:
        progress.baka_cascade_max = cascade_count


def on_state_read(progress: AchievementProgress, state: str, was_correct: bool):
    """Call when player responds to a state."""
    if was_correct:
        if state == "rambling":
            progress.rambling_reads += 1
        elif state == "bratty":
            progress.bratty_handled += 1
        elif state == "melting":
            progress.melting_caught += 1
        elif state in ("quiet", "vulnerable"):
            progress.quiet_handled += 1


def on_mode_enter(progress: AchievementProgress, mode: str):
    """Call when a mode is entered."""
    if mode not in progress.session_modes_entered:
        progress.session_modes_entered.append(mode)
    
    if mode == "love_bunny":
        progress.love_bunny_entries += 1
    elif mode == "starving":
        progress.starving_entries += 1
    elif mode == "hump_dog":
        progress.hump_dog_unlocked = True
    elif mode == "outhouse":
        progress.outhouse_discovered = True


def on_mode_complete(progress: AchievementProgress, mode: str):
    """Call when a mode is completed."""
    if mode == "love_bunny":
        progress.love_bunny_completions += 1


def on_edge(progress: AchievementProgress):
    """Call when an edge is completed."""
    progress.edges_completed += 1
    progress.session_edges += 1


def on_slip(progress: AchievementProgress):
    """Call when a slip occurs."""
    progress.slips_witnessed += 1


def on_wrong_hole(progress: AchievementProgress):
    """Call when a wrong hole event occurs."""
    progress.wrong_holes_witnessed += 1


def on_escape(progress: AchievementProgress):
    """Call when an escape occurs."""
    progress.escapes_witnessed += 1


def on_climax(progress: AchievementProgress):
    """Call when a climax occurs."""
    progress.total_climaxes += 1


def on_transcendence(progress: AchievementProgress):
    """Call when transcendence is reached."""
    progress.transcendence_reached += 1


def on_transcendence_complete(progress: AchievementProgress):
    """Call when transcendence is completed."""
    progress.transcendence_completions += 1


def on_combo_update(progress: AchievementProgress, current_combo: int):
    """Call when combo changes."""
    if current_combo > progress.max_combo_ever:
        progress.max_combo_ever = current_combo


def on_miss(progress: AchievementProgress):
    """Call when a miss occurs."""
    progress.session_misses += 1


# ═══════════════════════════════════════════════════════════════════════════════
#                    DIALOGUE-BASED ACHIEVEMENT TRACKING
# ═══════════════════════════════════════════════════════════════════════════════

def track_dialogue_achievements(progress: AchievementProgress, speaker: str, text: str, 
                                 emotional_state: str = None):
    """
    Track achievements based on dialogue content.
    Call this for every dialogue line displayed.
    """
    # Skip non-string content (e.g., SILENCE durations)
    if not isinstance(text, str):
        return
    
    text_lower = text.lower()
    
    # ─── MWEHH TRACKING ───
    if "mwehh" in text_lower or "mweh" in text_lower:
        progress.mwehh_heard += 1
        progress.session_mwehhs += 1
        
        # Track different mwehh states
        if emotional_state and emotional_state not in progress.mwehh_states_list:
            progress.mwehh_states_list.append(emotional_state)
            progress.mwehh_states_seen = len(progress.mwehh_states_list)
        
        # Check for triple mwehh in session
        if progress.session_mwehhs >= 3:
            progress.triple_mwehh_session = True
    
    # ─── BAKA TRACKING ───
    if "baka" in text_lower:
        progress.baka_heard += 1
        
        # Track rapid succession (baka cascade)
        # This needs state tracking, simplified to just count
        if speaker == "FIEND":
            progress.fiend_baka_used = True
    
    # ─── GOOD GIRL TRACKING ───
    if "good girl" in text_lower:
        progress.good_girl_said += 1
    
    # ─── SPECIAL MOMENTS ───
    if "...yours" in text_lower or "i'm yours" in text_lower or "yours..." in text_lower:
        progress.yours_admission = True
    
    if "please" in text_lower and speaker in ("BIRDSONG", "FIEND"):
        # Check if it's a genuine please (not sarcastic)
        if "..." in text or len(text) < 20:
            progress.genuine_please = True
    
    if "i need" in text_lower and speaker in ("BIRDSONG", "FIEND"):
        progress.i_need_moment = True
    
    # ─── UWU/OWO TRACKING ───
    if "uwu" in text_lower:
        progress.uwu_incident = True
    if "owo" in text_lower and speaker in ("BIRDSONG", "FIEND"):
        progress.owo_response = True
    
    # ─── NAME MOMENT ───
    if "[name]" in text_lower or "your name" in text_lower:
        progress.name_moment = True


def track_state_read(progress: AchievementProgress, state: str, handled_well: bool = True):
    """
    Track when player reads and responds to emotional states.
    Call when player makes a choice based on detected state.
    """
    if state == "rambling" and handled_well:
        progress.rambling_reads += 1
    elif state == "bratty" and handled_well:
        progress.bratty_handled += 1
    elif state == "melting" and handled_well:
        progress.melting_caught += 1
    elif state == "quiet" and handled_well:
        progress.quiet_handled += 1


def track_stare_break(progress: AchievementProgress):
    """Track when sustained eye contact breaks her."""
    progress.stare_breaks += 1
    progress.pure_silence_break = True


def track_special_mode(progress: AchievementProgress, mode: str):
    """Track entry into special modes."""
    if mode not in progress.session_modes_entered:
        progress.session_modes_entered.append(mode)
    
    if mode == "love_bunny":
        progress.love_bunny_entries += 1
    elif mode == "starving":
        progress.starving_entries += 1
    elif mode == "edge":
        progress.session_edges += 1


def track_mode_completion(progress: AchievementProgress, mode: str):
    """Track completion of special modes."""
    if mode == "love_bunny":
        progress.love_bunny_completions += 1
    elif mode == "edge":
        progress.edges_completed += 1
    elif mode == "transcendence":
        progress.transcendence_completions += 1


def on_session_end(progress: AchievementProgress, session_minutes: float, had_misses: bool):
    """Call at session end."""
    progress.sessions_completed += 1
    progress.total_minutes += int(session_minutes)
    
    if not had_misses and progress.session_misses == 0:
        progress.perfect_session_achieved = True
    
    # Check full spectrum
    required_modes = {'love_bunny', 'hump_dog', 'starving', 'edge'}
    if required_modes.issubset(set(progress.session_modes_entered)):
        progress.full_spectrum_session = True
    
    # Reset session tracking
    progress.reset_session()


def on_style_choice(progress: AchievementProgress, style: str, amount: int = 1):
    """Call when a style choice is made."""
    if style == "verbal":
        progress.style_verbal += amount
    elif style == "physical":
        progress.style_physical += amount
    elif style == "silent":
        progress.style_silent += amount


def on_tempo_choice(progress: AchievementProgress, tempo: str, amount: int = 1):
    """Call when a tempo choice is made."""
    if tempo == "patient":
        progress.tempo_patient += amount
    elif tempo == "eager":
        progress.tempo_eager += amount
    elif tempo == "aggressive":
        progress.tempo_aggressive += amount


def on_name_moment(progress: AchievementProgress):
    """Call when intimate name moment occurs."""
    progress.name_moment = True


def on_name_loop(progress: AchievementProgress):
    """Call when a 'say it again' name loop completes."""
    progress.name_loops_completed += 1


def on_good_girl_perfect(progress: AchievementProgress):
    """Call when 'good girl' lands with perfect timing."""
    progress.good_girl_perfect += 1


def on_mutual_silence(progress: AchievementProgress):
    """Call when mutual silence moment occurs."""
    progress.mutual_silence_achieved = True


