def build_reward_lightmap_audit() -> Dict[str, Dict[str, Any]]:
    """Return asset-presence data for release/debug audits."""
    root = _fiendish_asset_root()
    audit: Dict[str, Dict[str, Any]] = {}
    for pose, meta in REWARD_LIGHTMAP_DEFS.items():
        figure_path = os.path.join(root, f"{pose}_figure.txt")
        frame_path = os.path.join(root, f"{pose}_frame.txt")
        loop_dir = os.path.join(root, str(meta.get("loop_frames_dir") or f"{pose}_loop_frames"))
        try:
            loop_count = len([name for name in os.listdir(loop_dir) if str(name).startswith("frame_") and str(name).endswith(".txt")]) if os.path.isdir(loop_dir) else 0
        except Exception:
            loop_count = 0
        quality_hold = bool(pose in PANDORA_QUALITY_HOLD_POSES or meta.get("quality_hold"))
        active = bool(os.path.exists(figure_path) and pose in POSES and not quality_hold)
        audit[pose] = {
            "active": active,
            "registered": bool(pose in POSES),
            "quality_hold": quality_hold,
            "quality_hold_reason": str(meta.get("quality_hold", "")),
            "figure_path": figure_path,
            "frame_path": frame_path if os.path.exists(frame_path) else "",
            "loop_dir": loop_dir if os.path.isdir(loop_dir) else "",
            "loop_frame_count": int(loop_count),
            "flow": bool(meta.get("flow", False)),
            "story": bool(meta.get("story", False)),
            "trigger": str(meta.get("trigger", "")),
            "fallback": str(meta.get("fallback", "")),
        }
    return audit

