def get_required_pose_for_dialogue(dialogue_text: str, current_pose: str) -> Optional[str]:
    """
    Check if dialogue requires a specific pose orientation.
    Returns required pose or None if current is fine.
    """
    text_lower = dialogue_text.lower()
    
    # Check explicit trigger phrases first
    for phrase, required_pose in POSE_TRIGGER_PHRASES.items():
        if phrase in text_lower:
            if required_pose is None:
                return None  # Keep current
            if required_pose != current_pose:
                return required_pose
            return None
    
    # Check if current pose is forbidden for this dialogue
    current_context = POSE_CONTEXT.get(current_pose, {})
    forbids = current_context.get("forbids_dialogue", [])
    
    for forbidden in forbids:
        if forbidden in text_lower:
            # Need to find an allowed pose
            for tag, allowed_poses in DIALOGUE_POSE_REQUIREMENTS.items():
                if tag in text_lower and allowed_poses:
                    # Return first allowed pose that isn't current
                    for pose in allowed_poses:
                        if pose != current_pose:
                            return pose
    
    # Check if dialogue requires face visibility
    face_required_phrases = ["face", "look at", "eyes", "see you", "watching"]
    for phrase in face_required_phrases:
        if phrase in text_lower:
            if not current_context.get("can_see_face", True):
                # Current pose doesn't show face, need to switch
                return "face"
    
    return None


def validate_pose_for_context(pose: str, dialogue_context: dict) -> bool:
    """
    Check if a pose is valid for the given dialogue context.
    Returns True if pose is appropriate.
    """
    pose_ctx = POSE_CONTEXT.get(pose, {})
    
    # Check required tags
    required_tags = dialogue_context.get("requires_pose_tags", [])
    allows = pose_ctx.get("allows_dialogue", [])
    
    if required_tags:
        if not any(tag in allows for tag in required_tags):
            return False
    
    # Check forbidden tags
    forbidden_tags = dialogue_context.get("forbids_pose_tags", [])
    forbids = pose_ctx.get("forbids_dialogue", [])
    
    if forbidden_tags:
        if any(tag in forbids for tag in forbidden_tags):
            return False
    
    # Check face visibility
    if dialogue_context.get("requires_face", False):
        if not pose_ctx.get("can_see_face", True):
            return False
    
    # Check position
    required_position = dialogue_context.get("requires_position")
    if required_position:
        if pose_ctx.get("position") != required_position:
            return False
    
    return True


def get_best_pose_for_context(dialogue_context: dict, current_pose: str) -> str:
    """
    Get the best pose for a dialogue context.
    Prefers current pose if valid, otherwise finds best match.
    """
    # Check if current pose works
    if validate_pose_for_context(current_pose, dialogue_context):
        return current_pose
    
    # Find best alternative
    scores = []
    for pose, ctx in POSE_CONTEXT.items():
        if not validate_pose_for_context(pose, dialogue_context):
            continue
        
        score = 0
        
        # Prefer poses that match power dynamic
        if dialogue_context.get("power_dynamic"):
            if ctx.get("power_dynamic") == dialogue_context["power_dynamic"]:
                score += 3
        
        # Prefer poses that match intimacy level
        if dialogue_context.get("intimacy"):
            if ctx.get("intimacy") == dialogue_context["intimacy"]:
                score += 2
        
        # Prefer similar orientation to current
        current_ctx = POSE_CONTEXT.get(current_pose, {})
        if ctx.get("orientation") == current_ctx.get("orientation"):
            score += 1
        
        scores.append((pose, score))
    
    if scores:
        scores.sort(key=lambda x: -x[1])
        return scores[0][0]
    
    return current_pose  # Fallback


