def get_transition(from_pose: str, to_pose: str) -> TransitionType:
    """Get transition type between poses"""
    key = (from_pose, to_pose)
    if key in POSE_TRANSITIONS:
        return POSE_TRANSITIONS[key]
    # Check wildcards
    if ("*", to_pose) in POSE_TRANSITIONS:
        return POSE_TRANSITIONS[("*", to_pose)]
    if (from_pose, "*") in POSE_TRANSITIONS:
        return POSE_TRANSITIONS[(from_pose, "*")]
    return TransitionType.FADE  # Default

def get_mode_pose(mode: str, intensity: float) -> str:
    """Get pose for current mode and intensity (legacy fallback)"""
    poses = MODE_POSES.get(mode, MODE_POSES["gentle"])
    for (lo, hi), pose in poses.items():
        if lo <= intensity < hi:
            return pose
    return "squat"

def get_tree_pose(current_pose: str, combo: int, misses_in_row: int, intensity: float, is_climax: bool = False) -> str:
    """Get next pose using tree diagram based on momentum"""
    if current_pose not in POSE_TREE:
        return current_pose
    
    tree = POSE_TREE[current_pose]
    
    # Climax path
    if is_climax and "next_climax" in tree:
        return tree["next_climax"]
    
    # Surge path: high combo = escalate
    if combo >= MOMENTUM_SURGE_THRESHOLD:
        return tree.get("next_surge", tree["next_natural"])
    
    # Retreat path: too many misses = pull back
    if misses_in_row >= MOMENTUM_RETREAT_THRESHOLD:
        return tree.get("next_retreat", tree["next_natural"])
    
    # Natural progression
    return tree["next_natural"]

def _reward_pose_available(pose: str, available_poses: set) -> bool:
    resolved = POSE_ALIASES.get(str(pose or ""), str(pose or ""))
    if resolved in PANDORA_QUALITY_HOLD_POSES:
        return False
    return bool(resolved and resolved in available_poses)

def _reward_pose_or_fallback(pose: str, available_poses: set) -> Optional[str]:
    pose = str(pose or "")
    resolved = POSE_ALIASES.get(pose, pose)
    if resolved in PANDORA_QUALITY_HOLD_POSES:
        return None
    if _reward_pose_available(pose, available_poses):
        return resolved
    fallback = str((REWARD_LIGHTMAP_DEFS.get(pose) or {}).get("fallback") or "")
    if fallback and _reward_pose_available(fallback, available_poses):
        return POSE_ALIASES.get(fallback, fallback)
    return None

def select_reward_lightmap_pose(
    *,
    base_pose: str,
    mode: str,
    intensity: float,
    combo: int,
    accuracy: float,
    flow_mode: bool,
    sync_level: int,
    level: int,
    figure_response_level: int,
    frisson_tier: int,
    available_poses: set,
    afterglow_active: bool = False,
    special_active: bool = False,
) -> Optional[str]:
    """Explicit reward-lightmap trigger map. Returns None when the normal tree should win."""
    try:
        intensity = float(intensity or 0.0)
        combo = int(combo or 0)
        accuracy = float(accuracy or 0.0)
        level = int(level or 1)
        sync_level = int(sync_level or 0)
        figure_response_level = int(figure_response_level or 0)
        frisson_tier = int(frisson_tier or 0)
    except Exception:
        return None

    def pick(pose: str) -> Optional[str]:
        return _reward_pose_or_fallback(pose, available_poses)

    # Recovery/afterglow is the clearest authored reward context.
    if afterglow_active or (combo >= 10 and accuracy >= 0.82 and intensity <= 30):
        p = pick("kitsune_shrine_06")
        if p:
            return p

    # Optional canon rewards only activate when their assets are actually present.
    if level >= 9 and combo >= 18 and accuracy >= 0.84 and str(mode) in ("gentle", "steady"):
        p = pick("fox_shrine_low_sprawl")
        if p:
            return p
    if level >= 7 and combo >= 8 and accuracy >= 0.74 and intensity <= 55:
        p = pick("birdsong_standing_back")
        if p:
            return p

    # Highest-skill forward/rhythm-impact reward.
    if (special_active or sync_level >= 3 or combo >= 26) and (level >= 5 or frisson_tier >= 1) and accuracy >= 0.86 and intensity >= 60:
        p = pick("kitsune_shrine_09")
        if p:
            return p

    if combo >= 18 and accuracy >= 0.82 and intensity >= 55 and (level >= 5 or frisson_tier >= 1):
        p = pick("kitsune_shrine_04")
        if p:
            return p

    if combo >= 12 and accuracy >= 0.78 and intensity >= 35 and (level >= 3 or figure_response_level >= 1 or sync_level >= 1):
        p = pick("kitsune_shrine_02")
        if p:
            return p

    if combo >= 6 and accuracy >= 0.70 and 25 <= intensity <= 75:
        p = pick("kitsune_shrine_01")
        if p:
            return p

    if combo >= 4 and accuracy >= 0.68 and intensity <= 65:
        p = pick("kitsune_shrine_05")
        if p:
            return p

    return None

def get_undulation_profile(intensity: float, combo: int) -> dict:
    """Get figure undulation intensity based on state"""
    if combo >= 20:
        return UNDULATION_PROFILES["peak"]
    elif intensity >= 80:
        return UNDULATION_PROFILES["intense"]
    elif intensity >= 50:
        return UNDULATION_PROFILES["building"]
    elif intensity >= 25:
        return UNDULATION_PROFILES["warming"]
    else:
        return UNDULATION_PROFILES["calm"]

