# ═══════════════════════════════════════════════════════════════════════════════
# ═══════════════════════════════════════════════════════════════════════════════
#                      LIGHTMAP HIGHLIGHT SOFTENING
# ═══════════════════════════════════════════════════════════════════════════════
# Your pose *_figure.txt and *_frame.txt files use Unicode shade blocks (░▒▓█).
# The issue you called out ("white highlight blocks") usually comes from small,
# harsh bright clusters (▓/█) with crisp edges. We DO NOT remove ░ or alter the
# base shading; we only soften overly-blocky highlight *edges* and tiny speckles.

_SHADE_LEVEL = {' ': 0, '░': 1, '▒': 2, '▓': 3, '█': 4}
_LEVEL_SHADE = {0: ' ', 1: '░', 2: '▒', 3: '▓', 4: '█'}

# Toggle: set OGRE_SOFTEN_LIGHTMAP_HIGHLIGHTS=0 to disable highlight softening.
SOFTEN_LIGHTMAP_HIGHLIGHTS = os.environ.get('OGRE_SOFTEN_LIGHTMAP_HIGHLIGHTS', '1') != '0'

def _shade_level(ch: str) -> int:
    return _SHADE_LEVEL.get(ch, 0)

def _shade_char(level: int) -> str:
    return _LEVEL_SHADE.get(max(0, min(4, int(level))), ' ')

def _neighbors8(h, w, y, x):
    for dy in (-1, 0, 1):
        for dx in (-1, 0, 1):
            if dy == 0 and dx == 0:
                continue
            ny, nx = y + dy, x + dx
            if 0 <= ny < h and 0 <= nx < w:
                yield ny, nx

def _extract_bright_components(grid, bright_level=3):
    """Return list of components as lists of (y,x) where shade_level >= bright_level."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    seen = [[False]*w for _ in range(h)]
    comps = []
    for y in range(h):
        for x in range(w):
            if seen[y][x]:
                continue
            if _shade_level(grid[y][x]) < bright_level:
                continue
            # BFS
            q = [(y, x)]
            seen[y][x] = True
            comp = [(y, x)]
            while q:
                cy, cx = q.pop()
                for ny, nx in _neighbors8(h, w, cy, cx):
                    if seen[ny][nx]:
                        continue
                    if _shade_level(grid[ny][nx]) >= bright_level:
                        seen[ny][nx] = True
                        q.append((ny, nx))
                        comp.append((ny, nx))
            comps.append(comp)
    return comps

def preprocess_lightmap_lines(lines, do_smooth=True):
    """Softens harsh highlight blocks without touching the underlying ░ base shading."""
    if not lines:
        return lines

    if do_smooth and not SOFTEN_LIGHTMAP_HIGHLIGHTS:
        do_smooth = False

    # Keep exact widths stable.
    w = max((len(l) for l in lines), default=0)
    grid = [list(l.ljust(w)) for l in lines]
    if not do_smooth:
        return [''.join(row) for row in grid]

    h = len(grid)

    # 1) Downgrade tiny bright speckles (components of ▓/█ that are too small).
    comps = _extract_bright_components(grid, bright_level=3)
    for comp in comps:
        if len(comp) <= 3:
            for (y, x) in comp:
                lvl = _shade_level(grid[y][x])
                grid[y][x] = _shade_char(lvl - 1)

    # 2) Soften hard edges of larger highlight blobs by lowering only boundary cells.
    # Boundary = a bright cell adjacent to any lower-level cell.
    # This keeps "core" highlights intact, but removes chunky square borders.
    for comp in comps:
        if len(comp) <= 3:
            continue
        for (y, x) in comp:
            lvl = _shade_level(grid[y][x])
            if lvl < 3:
                continue
            is_boundary = False
            for ny, nx in _neighbors8(h, w, y, x):
                if _shade_level(grid[ny][nx]) < lvl:
                    is_boundary = True
                    break
            if is_boundary:
                grid[y][x] = _shade_char(lvl - 1)

    return [''.join(row) for row in grid]

#                         LIGHTMAP LOADER
# ═══════════════════════════════════════════════════════════════════════════════

@dataclass
class Lightmap:
    figure: List[str]
    frame: List[str]
    width: int
    height: int
    loop_frames: List[List[str]] = field(default_factory=list)
    loop_delay_ms: int = 0

def load_all_lightmaps() -> Dict[str, Lightmap]:
    """Load all lightmap files"""
    lightmaps = {}
    script_dir = _fiendish_asset_root()
    
    for pose in POSES:
        fig_path = os.path.join(script_dir, f"{pose}_figure.txt")
        frame_path = os.path.join(script_dir, f"{pose}_frame.txt")
        loop_dir = os.path.join(script_dir, f"{pose}_loop_frames")
        
        if os.path.exists(fig_path):
            try:
                with open(fig_path, 'r', encoding='utf-8') as f:
                    figure = f.read().split('\n')
                frame = []
                if os.path.exists(frame_path):
                    with open(frame_path, 'r', encoding='utf-8') as f:
                        frame = f.read().split('\n')
                
                max_h = max(len(figure), len(frame) if frame else 0)
                while len(figure) < max_h: figure.append('')
                while len(frame) < max_h: frame.append('')

                preserve_cells = bool((REWARD_LIGHTMAP_DEFS.get(pose) or {}).get("preserve_cells", False))

                # Non-canon legacy assets may still get tiny highlight cleanup. Canon
                # reward assets must preserve authored terminal-cell polarity exactly.
                figure = preprocess_lightmap_lines(figure, do_smooth=not preserve_cells)
                frame = preprocess_lightmap_lines(frame, do_smooth=False)
                loop_frames: List[List[str]] = []
                if os.path.isdir(loop_dir):
                    try:
                        for loop_name in sorted(os.listdir(loop_dir)):
                            if not (str(loop_name).startswith("frame_") and str(loop_name).endswith(".txt")):
                                continue
                            loop_path = os.path.join(loop_dir, loop_name)
                            with open(loop_path, 'r', encoding='utf-8') as lf:
                                loop_lines = lf.read().split('\n')
                            while len(loop_lines) < max_h:
                                loop_lines.append('')
                            loop_frames.append(preprocess_lightmap_lines(loop_lines, do_smooth=not preserve_cells))
                    except Exception:
                        loop_frames = []
                
                width = max(max(len(l) for l in figure), max(len(l) for l in frame) if frame else 0)
                for loop_lines in loop_frames:
                    try:
                        width = max(width, max(len(l) for l in loop_lines) if loop_lines else 0)
                        max_h = max(max_h, len(loop_lines))
                    except Exception:
                        pass
                delay_ms = int((REWARD_LIGHTMAP_DEFS.get(pose) or {}).get("loop_delay_ms", 0) or 0)
                lightmaps[pose] = Lightmap(figure=figure, frame=frame, width=width, height=max_h, loop_frames=loop_frames, loop_delay_ms=delay_ms)
            except:
                pass
    
    return lightmaps

# ═══════════════════════════════════════════════════════════════════════════════
#                         LIGHTMAP RENDERER
# ═══════════════════════════════════════════════════════════════════════════════

class LightmapRenderer:
    """Handles pose rendering with transitions and effects"""
    
    def __init__(self, lightmaps: Dict[str, Lightmap]):
        self.lightmaps = lightmaps
        self.current_pose = "stand_backfacing"
        self.target_pose = None
        self.transition_t = 0.0
        self.transition_type = TransitionType.INSTANT
        
        # Breathing/sway animation
        self.breath_phase = 0.0
        self.sway_phase = 0.0
        self.state_phase = 0.0
        self.playback_context = "dialogue"
        self.state_energy = "safe"
        self.state_strength = 0.0
        self.rhythm_impact_t = 0.0
        self.rhythm_impact_duration = 0.0
        self.rhythm_impact_strength = 0.0
        self.rhythm_impact_dir = 1
        self.rhythm_impact_lane = ""
        
        # Effects
        self.shake_t = 0.0
        self.shake_amp = 0.0
        self.flash_t = 0.0
        self.flash_color = 0
        self.dim_factor = 1.0  # For dimming during cooldowns
        
        # Hit effects
        self.hit_flash_t = 0.0
        self.hit_lane = None
        
        # Momentum tracking for pose tree
        self.momentum_combo = 0
        self.momentum_misses = 0
        self.undulation = UNDULATION_PROFILES["calm"]
        self.pose_timer = 0.0  # Time in current pose
        self.pose_change_cooldown = 2.0  # Minimum time between natural pose changes
        
        # ═══════════════════════════════════════════════════════════════════════
        # BODY DETAIL OVERLAY - Humidity, sweat, hair, folds
        # ═══════════════════════════════════════════════════════════════════════
        self.body_overlay = BodyDetailOverlay()
        self.pleasure = 0.0      # Track pleasure for overlay
        self.depth = 0.0         # Track depth for overlay
        self.intensity = 0.0     # Track intensity for overlay
    
    def update_momentum(self, combo: int, misses_in_row: int, intensity: float):
        """Update momentum state from gameplay"""
        self.momentum_combo = combo
        self.momentum_misses = misses_in_row
        self.undulation = get_undulation_profile(intensity, combo)

    def set_playback_context(self, context: str):
        """Set how strongly gameplay may season the authored lightmap loop."""
        context = str(context or "dialogue").lower()
        if context not in LIGHTMAP_PLAYBACK_CONTEXTS:
            context = "dialogue"
        self.playback_context = context

    def configure_playback_modifiers(
        self,
        context: str = "gameplay",
        flow_mode: bool = False,
        combo: int = 0,
        misses_in_row: int = 0,
        intensity: float = 0.0,
        sync_level: int = 0,
        reward_active: bool = False,
        pause_active: bool = False,
    ):
        """
        Runtime posture modifier layer.

        Author owns pose identity: base movement remains dominant. Gameplay only
        adds tiny state-energy offsets and brief rhythm impacts that return to
        the authored loop.
        """
        self.set_playback_context(context)
        combo = max(0, int(combo or 0))
        misses_in_row = max(0, int(misses_in_row or 0))
        intensity = max(0.0, min(100.0, float(intensity or 0.0)))
        sync_level = max(0, int(sync_level or 0))

        if reward_active or sync_level >= 2 or combo >= 24:
            state = "reward"
        elif misses_in_row >= 2:
            state = "danger"
        elif flow_mode and (sync_level >= 1 or combo >= 12):
            state = "focus"
        elif combo >= 6 or intensity >= 55.0:
            state = "attention"
        elif pause_active or intensity <= 20.0:
            state = "safe"
        else:
            state = "social"

        if flow_mode and state == "attention" and combo >= 10:
            state = "playful"

        base = (intensity / 100.0) * 0.65 + min(combo, 24) / 48.0
        if state == "reward":
            base *= 0.45
        elif state == "safe":
            base *= 0.35
        elif state == "danger":
            base = max(base, 0.55)
        self.state_energy = state
        self.state_strength = max(0.0, min(1.0, base))

    def _quantize_cell_offset(self, value: float) -> int:
        """Convert sub-cell intent into rare one-cell movement."""
        if value >= 0.55:
            return 1
        if value <= -0.55:
            return -1
        return 0

    def _pose_modifier_origin(self) -> str:
        pose = POSE_ALIASES.get(self.current_pose, self.current_pose)
        return POSE_MODIFIER_ORIGINS.get(pose, POSE_MODIFIER_ORIGINS.get(self.current_pose, "core"))

    def _posture_modifier_offset(self, row_idx: int, total_rows: int) -> Tuple[int, int]:
        """Small row-banded state modifier: gameplay animates posture, not body."""
        if total_rows <= 1:
            return 0, 0
        context = LIGHTMAP_PLAYBACK_CONTEXTS.get(self.playback_context, LIGHTMAP_PLAYBACK_CONTEXTS["dialogue"])
        state = LIGHTMAP_STATE_MODIFIERS.get(self.state_energy, LIGHTMAP_STATE_MODIFIERS["safe"])
        scale = float(context.get("scale", 0.4)) * float(state.get("amp", 0.3)) * float(self.state_strength or 0.0)
        if scale <= 0.04:
            return 0, 0

        row = row_idx / max(1, total_rows - 1)
        origin = self._pose_modifier_origin()
        phase = float(getattr(self, "state_phase", 0.0))
        wave = math.sin(phase * math.pi * 2.0)
        delay_wave = math.sin((phase - 0.18) * math.pi * 2.0)
        recovery_wave = math.sin((phase - 0.33) * math.pi * 2.0)

        x = 0
        y = 0

        if origin == "hip":
            if row >= 0.45:
                x = self._quantize_cell_offset(wave * scale * 1.15)
            elif row >= 0.24:
                x = self._quantize_cell_offset(delay_wave * scale * 0.65)
        elif origin == "lower":
            if row >= 0.50:
                x = self._quantize_cell_offset(wave * scale)
            elif row >= 0.28:
                x = self._quantize_cell_offset(delay_wave * scale * 0.45)
        elif origin == "upper":
            if row <= 0.42:
                x = self._quantize_cell_offset(delay_wave * scale * 0.75)
                y = self._quantize_cell_offset(-abs(recovery_wave) * scale * 0.35)
        elif origin == "distributed":
            if row >= 0.62:
                x = self._quantize_cell_offset(wave * scale * 0.80)
            elif row >= 0.32:
                x = self._quantize_cell_offset(delay_wave * scale * 0.55)
            elif row >= 0.12:
                x = self._quantize_cell_offset(recovery_wave * scale * 0.45)
        else:
            if 0.25 <= row <= 0.72:
                x = self._quantize_cell_offset(wave * scale * 0.65)

        if self.state_energy == "reward":
            # Reward/highlight states let the authored pose loop speak.
            gate = int((phase * 4.0) % 4)
            if gate not in (1,):
                x = 0
            y = 0
        return x, y

    def _rhythm_impact_offset(self, row_idx: int, total_rows: int) -> Tuple[int, int]:
        """Brief hit response with delayed recovery back into the authored loop."""
        duration = float(getattr(self, "rhythm_impact_duration", 0.0) or 0.0)
        remaining = float(getattr(self, "rhythm_impact_t", 0.0) or 0.0)
        if duration <= 0.0 or remaining <= 0.0 or total_rows <= 1:
            return 0, 0

        progress = 1.0 - max(0.0, min(1.0, remaining / duration))
        row = row_idx / max(1, total_rows - 1)
        origin = self._pose_modifier_origin()
        pose_key = POSE_ALIASES.get(self.current_pose, self.current_pose)
        direction = int(getattr(self, "rhythm_impact_dir", 1) or 1)
        strength = float(getattr(self, "rhythm_impact_strength", 1.0) or 1.0)
        context = LIGHTMAP_PLAYBACK_CONTEXTS.get(self.playback_context, LIGHTMAP_PLAYBACK_CONTEXTS["dialogue"])
        if float(context.get("scale", 1.0)) < 0.5:
            strength *= 0.35

        layer_weight = 0.0
        if origin in ("hip", "lower") and row >= 0.45:
            layer_weight = 1.0
        elif origin == "distributed":
            layer_weight = 0.75 if row >= 0.55 else 0.45 if row >= 0.25 else 0.25
        elif origin == "upper" and row <= 0.45:
            layer_weight = 0.6
        elif 0.25 <= row <= 0.75:
            layer_weight = 0.55
        if layer_weight <= 0.0:
            return 0, 0

        if progress < 0.18:
            x = direction
            y = -1 if strength >= 1.25 and row < 0.70 else 0
            if pose_key == "squat":
                y = 0
        elif progress < 0.48:
            x = -direction if layer_weight >= 0.75 else 0
            y = 0
        elif progress < 0.74:
            x = direction if strength >= 1.35 and layer_weight >= 0.75 else 0
            y = 0
        else:
            x = 0
            y = 0
        return x, y
    
    def get_tree_suggested_pose(self, is_climax: bool = False) -> str:
        """Get next pose suggestion from tree based on momentum"""
        if self.pose_timer < self.pose_change_cooldown:
            return self.current_pose
        return get_tree_pose(
            self.current_pose, 
            self.momentum_combo, 
            self.momentum_misses, 
            0,  # intensity handled by undulation
            is_climax
        )
    
    def set_pose(self, pose: str, instant: bool = False):
        """Request pose change with transition"""
        pose = POSE_ALIASES.get(pose, pose)
        if pose == self.current_pose:
            return
        if pose not in self.lightmaps:
            return
        
        if instant or self.target_pose is not None:
            # Complete any pending transition instantly
            if self.target_pose:
                self.current_pose = self.target_pose
            self.current_pose = pose
            self.target_pose = None
            self.transition_t = 0
        else:
            self.target_pose = pose
            self.transition_type = get_transition(self.current_pose, pose)
            self.transition_t = self.transition_type.value
            
            # Flash effect for flash transitions
            if self.transition_type == TransitionType.FLASH:
                self.flash_t = 0.15
                self.flash_color = 2  # White
        
        # Reset pose timer on pose change
        self.pose_timer = 0.0
    
    def trigger_hit(self, lane: str, quality: str, intensity: float):
        """Trigger hit effect on lightmap"""
        self.hit_flash_t = 0.15 if quality == "perfect" else 0.1 if quality == "great" else 0.05
        self.hit_lane = lane
        lane_dir = {"A": -1, "S": 1, "B": -1, "SPACE": 1}
        quality_strength = {"good": 0.85, "great": 1.0, "perfect": 1.35}
        self.rhythm_impact_dir = lane_dir.get(str(lane or "").upper(), 1)
        self.rhythm_impact_strength = quality_strength.get(str(quality or "").lower(), 0.75)
        self.rhythm_impact_duration = 0.26 if quality == "perfect" else 0.22
        self.rhythm_impact_t = self.rhythm_impact_duration
        self.rhythm_impact_lane = str(lane or "")
        
        # Shake on strong hits at high intensity
        if quality == "perfect" and intensity > 50:
            self.shake_t = 0.2
            self.shake_amp = 1.0 + intensity / 50
    
    def trigger_shake(self, duration: float, amplitude: float):
        """Trigger screen shake"""
        self.shake_t = duration
        self.shake_amp = amplitude
    
    def trigger_flash(self, color: int, duration: float = 0.2):
        """Trigger screen flash"""
        self.flash_t = duration
        self.flash_color = color
    
    def set_dim(self, factor: float):
        """Set dim factor (0-1, 1 = normal)"""
        self.dim_factor = factor
    
    def update(self, dt: float, intensity: float, pleasure: float = 0.0, depth: float = 0.0):
        """Update animations and transitions - ENHANCED for more visible movement"""
        # Track time in current pose
        self.pose_timer += dt
        
        # Store state for overlay
        self.intensity = intensity
        self.pleasure = pleasure
        self.depth = depth
        
        # Update body detail overlay
        self.body_overlay.update(dt, intensity, pleasure, depth)
        
        # Transition
        if self.transition_t > 0:
            self.transition_t = max(0, self.transition_t - dt)
            if self.transition_t <= 0 and self.target_pose:
                self.current_pose = self.target_pose
                self.target_pose = None
        
        # Breathing (uses undulation profile) - ENHANCED base rate
        breath_base = 0.7 + intensity / 40  # More baseline breathing
        breath_speed = breath_base * self.undulation.get("breathe_amp", 0.5)
        self.breath_phase += dt * breath_speed
        
        # Sway (uses undulation profile) - ENHANCED base rate
        sway_base = 0.5 + intensity / 60  # More baseline sway
        sway_speed = sway_base * self.undulation.get("sway_amp", 0.2)
        self.sway_phase += dt * sway_speed
        
        # BRAT WIGGLE - Separate faster oscillation for bratty energy
        # Disabled during climax (wiggle = 0)
        wiggle_speed = 2.5 + intensity / 30  # Faster than sway
        self.wiggle_phase = getattr(self, 'wiggle_phase', 0.0)
        self.wiggle_phase += dt * wiggle_speed * self.undulation.get("wiggle", 0.2)

        # Runtime state-energy modifier: slow posture drift, capped in render.
        context = LIGHTMAP_PLAYBACK_CONTEXTS.get(self.playback_context, LIGHTMAP_PLAYBACK_CONTEXTS["dialogue"])
        state = LIGHTMAP_STATE_MODIFIERS.get(self.state_energy, LIGHTMAP_STATE_MODIFIERS["safe"])
        state_speed = (0.09 + intensity / 220.0) * float(context.get("speed", 0.45)) * float(state.get("pause", 1.0))
        self.state_phase += dt * state_speed
        
        # TREMBLE - High frequency micro-shake for intense moments
        self.tremble_phase = getattr(self, 'tremble_phase', 0.0)
        tremble_speed = 8.0 + intensity / 10  # Very fast
        self.tremble_phase += dt * tremble_speed * self.undulation.get("tremble", 0.0)
        
        # Decay effects
        self.shake_t = max(0, self.shake_t - dt)
        self.flash_t = max(0, self.flash_t - dt)
        self.hit_flash_t = max(0, self.hit_flash_t - dt)
        self.rhythm_impact_t = max(0, float(getattr(self, "rhythm_impact_t", 0.0) or 0.0) - dt)
        
        if self.shake_t <= 0:
            self.shake_amp = 0
    
    def set_undulation_profile(self, profile_name: str):
        """Set undulation profile directly (for cutscenes, climax, etc)"""
        if profile_name in UNDULATION_PROFILES:
            self.undulation = UNDULATION_PROFILES[profile_name]
    
    def render(self, scr, top: int, bottom: int, width: int, intensity: float):
        """Render lightmap with pose-specific body movements"""
        h, w = scr.getmaxyx()
        cx = width // 2
        
        lightmap = self.lightmaps.get(self.current_pose)
        if not lightmap:
            return
        
        # Get movement profile for current pose
        movement = POSE_MOVEMENTS.get(self.current_pose, {
            "type": "breathe", "y_amp": 0.5, "x_amp": 0.3, 
            "y_speed": 0.3, "x_speed": 0.2
        })
        
        # Calculate available height
        available_h = bottom - top
        figure_source = lightmap.figure
        try:
            loop_frames = list(getattr(lightmap, "loop_frames", []) or [])
            if loop_frames:
                delay_ms = max(40, int(getattr(lightmap, "loop_delay_ms", 0) or 230))
                idx = int((float(getattr(self, "pose_timer", 0.0) or 0.0) * 1000.0) / float(delay_ms)) % len(loop_frames)
                figure_source = loop_frames[idx]
        except Exception:
            figure_source = lightmap.figure
        
        # Scale lines if needed
        if lightmap.height > available_h:
            step = lightmap.height / available_h
            frame_lines = [lightmap.frame[int(i * step)] if int(i * step) < len(lightmap.frame) else "" 
                          for i in range(available_h)]
            figure_lines = [figure_source[int(i * step)] if int(i * step) < len(figure_source) else "" 
                           for i in range(available_h)]
        else:
            frame_lines = lightmap.frame[:available_h]
            figure_lines = figure_source[:available_h]
        
        # Center vertically
        start_y = top
        if len(frame_lines) < available_h:
            start_y = top + (available_h - len(frame_lines)) // 2
        
        # === FRAME (static background) ===
        frame_x = cx - lightmap.width // 2
        
        for i, line in enumerate(frame_lines):
            if not line:
                continue
            y = start_y + i
            if top <= y < bottom and frame_x < w:
                try:
                    scr.addstr(y, max(0, frame_x), line[:w-1], curses.A_DIM)
                except:
                    pass
        
        # === FIGURE (pose-specific movement) ===
        
        # Get amplitude scaled by intensity (more intense = more movement)
        intensity_scale = 0.5 + (intensity / 100) * 1.0  # 0.5 to 1.5
        
        y_amp = movement["y_amp"] * intensity_scale
        x_amp = movement["x_amp"] * intensity_scale
        
        # Calculate Y offset based on movement type
        move_type = movement.get("type", "breathe")
        
        if move_type == "cat_arch":
            # Special: arch UP (negative) then down - like a cat getting tingles
            # Use abs(sin) to make it always arch UP from baseline
            arch = math.sin(self.breath_phase * math.pi * 2 * movement["y_speed"])
            # Arch goes UP (negative Y in screen coords) when positive
            y_offset = int(-abs(arch) * y_amp)  # Always UP from baseline
        elif move_type == "bounce":
            # Quick bounce synced to rhythm - sharper peaks
            bounce = abs(math.sin(self.breath_phase * math.pi * 2 * movement["y_speed"]))
            y_offset = int(-bounce * y_amp)  # Bounce UP
        elif move_type == "breathe_deep":
            # Very slow, smooth sine wave
            y_offset = int(math.sin(self.breath_phase * math.pi * 2 * movement["y_speed"]) * y_amp)
        else:
            # Default: gentle sine wave breathing
            y_offset = int(math.sin(self.breath_phase * math.pi * 2 * movement["y_speed"]) * y_amp)
        
        # Calculate X offset (sway/wiggle)
        if move_type == "walk":
            # Walking has pronounced alternating sway
            x_offset = int(math.sin(self.sway_phase * math.pi * 2 * movement["x_speed"]) * x_amp)
        elif move_type == "tease":
            # Playful, slightly irregular sway
            x_offset = int(math.sin(self.sway_phase * math.pi * 2 * movement["x_speed"]) * x_amp)
        elif move_type == "tension":
            # Trembling - small rapid oscillation
            x_offset = int(math.sin(self.sway_phase * math.pi * 8) * x_amp * 0.5)
        else:
            # Default sway
            x_offset = int(math.sin(self.sway_phase * math.pi * 2 * movement["x_speed"]) * x_amp)
        
        # ═══════════════════════════════════════════════════════════════════════
        # BRAT WIGGLE - Faster lateral movement (bratty energy)
        # Layered on top of sway, controlled by undulation "wiggle" param
        # Disabled during climax (wiggle = 0)
        # ═══════════════════════════════════════════════════════════════════════
        wiggle_phase = getattr(self, 'wiggle_phase', 0.0)
        wiggle_amp = self.undulation.get("wiggle", 0.15) * intensity_scale * 1.5
        wiggle_x = int(math.sin(wiggle_phase * math.pi * 4) * wiggle_amp)  # Faster than sway
        
        # ═══════════════════════════════════════════════════════════════════════
        # TREMBLE - High frequency micro-shake for intense moments
        # ═══════════════════════════════════════════════════════════════════════
        tremble_phase = getattr(self, 'tremble_phase', 0.0)
        tremble_amp = self.undulation.get("tremble", 0.0) * intensity_scale
        tremble_x = int(math.sin(tremble_phase * math.pi * 12) * tremble_amp * 0.8)  # Very fast, small
        tremble_y = int(math.cos(tremble_phase * math.pi * 10) * tremble_amp * 0.4)
        
        # Shake (from external trigger like slip/wrong hole)
        shake_x = int(random.uniform(-1, 1) * self.shake_amp) if self.shake_t > 0 else 0
        shake_y = int(random.uniform(-0.5, 0.5) * self.shake_amp) if self.shake_t > 0 else 0
        
        # Combine authored/legacy offsets first. State and rhythm modifiers are
        # row-banded below so gameplay can season posture without hijacking it.
        fig_x = cx - lightmap.width // 2 + x_offset + wiggle_x + tremble_x + shake_x
        fig_y_offset = y_offset + tremble_y + shake_y
        
        # Render figure character by character
        for i, line in enumerate(figure_lines):
            if not line or not line.strip():
                continue
            
            posture_x, posture_y = self._posture_modifier_offset(i, len(figure_lines))
            impact_x, impact_y = self._rhythm_impact_offset(i, len(figure_lines))
            y = start_y + i + fig_y_offset + posture_y + impact_y
            if not (top <= y < bottom):
                continue
            
            for j, char in enumerate(line):
                if char == ' ':
                    continue
                
                px = fig_x + posture_x + impact_x + j
                if 0 <= px < w - 1:
                    try:
                        scr.addch(y, px, char)
                    except:
                        pass
        
        # ═══════════════════════════════════════════════════════════════════════
        # BODY DETAIL OVERLAY - Humidity, sweat, hair, folds
        # Render AFTER figure so details appear on top
        # ═══════════════════════════════════════════════════════════════════════
        
        # Calculate figure center for overlay positioning
        center_row = len(figure_lines) // 2
        center_posture_x, center_posture_y = self._posture_modifier_offset(center_row, len(figure_lines))
        center_impact_x, center_impact_y = self._rhythm_impact_offset(center_row, len(figure_lines))
        fig_cy = start_y + center_row + fig_y_offset + center_posture_y + center_impact_y
        fig_cx_center = fig_x + lightmap.width // 2 + center_posture_x + center_impact_x
        
        # Estimate pelvic region center (roughly 60% down the figure)
        pelvis_row = int(len(figure_lines) * 0.6)
        pelvis_posture_x, pelvis_posture_y = self._posture_modifier_offset(pelvis_row, len(figure_lines))
        pelvis_impact_x, pelvis_impact_y = self._rhythm_impact_offset(pelvis_row, len(figure_lines))
        pelvis_y = start_y + pelvis_row + fig_y_offset + pelvis_posture_y + pelvis_impact_y
        pelvis_cx_center = fig_x + lightmap.width // 2 + pelvis_posture_x + pelvis_impact_x
        
        # Render body detail overlay
        self.body_overlay.render(
            scr, pelvis_cx_center, pelvis_y, self.current_pose,
            self.pleasure, self.intensity, self.depth
        )

