# ──────────────────────────────────────────────────────────────────────────────
# SWEAT CURVES: per-pose build control (safe, non-explicit)
# ──────────────────────────────────────────────────────────────────────────────
POSE_SWEAT_CURVES = {
    # onset/full are in 0..1 combined space, gain scales final sweat scalar slightly
    "stand_backfacing": {"onset": 0.18, "full": 0.86, "gain": 1.00, "dur_mix": 0.38},
    "downward":         {"onset": 0.14, "full": 0.82, "gain": 1.12, "dur_mix": 0.42},
    "squat":            {"onset": 0.16, "full": 0.84, "gain": 1.06, "dur_mix": 0.40},
}

def _smoothstep(edge0: float, edge1: float, x: float) -> float:
    if edge0 == edge1:
        return 1.0 if x >= edge1 else 0.0
    t = max(0.0, min(1.0, (x - edge0) / (edge1 - edge0)))
    return t * t * (3 - 2 * t)

def get_sweat_scalar(pose: str, intensity: float, duration: float) -> float:
    """Return sweat scalar 0..1 with per-pose build curves.
    Keeps the same probability space, but makes the build feel coherent per pose.
    """
    intensity_n = max(0.0, min(1.0, (intensity or 0.0) / 100.0))
    duration_n = max(0.0, min(1.0, (duration or 0.0) / 600.0))  # cap at 10min
    cfg = POSE_SWEAT_CURVES.get(pose, {"onset": 0.18, "full": 0.86, "gain": 1.0, "dur_mix": 0.38})
    combined = intensity_n * (1.0 - cfg["dur_mix"]) + duration_n * cfg["dur_mix"]
    built = _smoothstep(cfg["onset"], cfg["full"], combined)
    return max(0.0, min(1.0, built * cfg["gain"]))

def get_sweat_level(intensity: float, duration: float) -> int:
    """Legacy sweat level 0-4 (kept for compatibility)."""
    # Default pose-less scalar (old behavior-ish)
    intensity_n = max(0.0, min(1.0, (intensity or 0.0) / 100.0))
    duration_n = max(0.0, min(1.0, (duration or 0.0) / 600.0))
    combined = intensity_n * 0.6 + duration_n * 0.4
    if combined < 0.2:
        return 0
    elif combined < 0.4:
        return 1
    elif combined < 0.6:
        return 2
    elif combined < 0.8:
        return 3
    else:
        return 4
# ═══════════════════════════════════════════════════════════════════════════════
#                    SIMPLIFIED SWEAT & FOLD RENDERER
# ═══════════════════════════════════════════════════════════════════════════════


# Toggle: set OGRE_DEBUG_SWEAT=1 to visualize sweat source anchors and drip path points.
DEBUG_SWEAT_SOURCES = os.environ.get('OGRE_DEBUG_SWEAT', '0') == '1'
# Default: disable sweat/fold overlay because non-shader cell chars can harm lightmap readability.
# Set OGRE_DISABLE_SWEAT=0 to re-enable.
OGRE_DISABLE_SWEAT = os.environ.get('OGRE_DISABLE_SWEAT', '1') == '1'
class BodyDetailOverlay:
    """
    Renders sweat drips and body folds.
    
    Philosophy: Bodies sweat. Bodies fold. That's it.
    No fantasy humidity auras. Just realism.
    """
    def __init__(self):
        self.active_drips = []           # Currently falling sweat drops
        self.session_duration = 0.0      # Time since start
        self.last_pose = None            # Track pose changes

        # Persistent "moisture" map in figure-local coords (x,y)->strength.
        # This creates pooling + runoff illusions without explicit lines.
        self.moisture = {}

        # Thin-film "humidity sheen" map. Separate from moisture:
        # - film = clinging gloss / damp skin
        # - moisture = pooled/runoff / heavier wetness
        self.film = {}

        # Last frame dt (for frame-rate independent spawning)
        self._last_dt = 1.0 / 30.0

        self._rng = random.Random()
    def update(self, dt: float, intensity: float, pleasure: float = 0.0, depth: float = 0.0):
        """Update sweat drip state"""
        self.session_duration += dt
        self._last_dt = dt
        
        # Move existing drips (gravity)
        surviving_drips = []
        for drip in self.active_drips:
            drip['age'] += dt
            drip['y'] += drip['vy'] * dt
            drip['vy'] += 1.5 * dt  # Gravity
            
            # Drips survive for 2-4 seconds
            if drip['age'] < drip['lifespan'] and drip['y'] < 12:
                surviving_drips.append(drip)
        

        self.active_drips = surviving_drips

        # Moisture map decay + runoff (subtle pooling illusion)
        # Keep keys small: only meaningful moisture survives.
        if self.moisture:
            decay = math.exp(-dt * 0.35)
            flowed = {}
            for (mx, my), val in list(self.moisture.items()):
                v = val * decay
                if v < 0.03:
                    continue

                # Flow strength depends on height: lower areas pool more.
                flow_frac = 0.18 if my < 2 else (0.10 if my < 5 else 0.05)
                flow = v * flow_frac

                keep = v - flow
                flowed[(mx, my)] = flowed.get((mx, my), 0.0) + keep

                if flow > 0.0:
                    # Gentle drift, mostly downward
                    dx = self._rng.choice([0, 0, 0, -1, 1])
                    ny = my + 1
                    nx = mx + dx
                    flowed[(nx, ny)] = flowed.get((nx, ny), 0.0) + flow

            # Clamp + prune
            self.moisture = {k: max(0.0, min(1.0, v)) for k, v in flowed.items() if abs(k[0]) <= 10 and -18 <= k[1] <= 12}

        # Humid film decay + gentle creep (slower than moisture).
        # This is the "humidity" layer: a clinging sheen that can later seed runoff.
        if self.film:
            fdecay = math.exp(-dt * 0.18)
            fflowed = {}
            for (fx, fy), val in list(self.film.items()):
                v = val * fdecay
                if v < 0.02:
                    continue

                # Very gentle downward creep, plus slight lateral diffusion.
                creep_frac = 0.06 if fy < 2 else (0.04 if fy < 5 else 0.025)
                creep = v * creep_frac
                keep = v - creep
                fflowed[(fx, fy)] = fflowed.get((fx, fy), 0.0) + keep

                if creep > 0.0:
                    dx = self._rng.choice([0, 0, 0, -1, 1])
                    nx = fx + dx
                    ny = fy + (1 if self._rng.random() < 0.85 else 0)
                    fflowed[(nx, ny)] = fflowed.get((nx, ny), 0.0) + creep

                    # Tiny diffusion for "humid blur" instead of hard droplets.
                    if self._rng.random() < 0.18:
                        sx = fx + self._rng.choice([-1, 1])
                        fflowed[(sx, fy)] = fflowed.get((sx, fy), 0.0) + creep * 0.10

            # Clamp + prune
            self.film = {k: max(0.0, min(1.0, v)) for k, v in fflowed.items() if abs(k[0]) <= 12 and -18 <= k[1] <= 12}

    def render(self, scr, fig_cx: int, fig_cy: int, pose: str,
               pleasure: float, intensity: float, depth: float = 0.0):
        """Render sweat and folds at figure position"""

        # Hard disable: remove all sweat/fold overlay to preserve lightmap clarity.
        if OGRE_DISABLE_SWEAT:
            return

        h, w = scr.getmaxyx()

        sweat_scalar = get_sweat_scalar(pose, intensity, self.session_duration)
        sweat_level = int(round(max(0.0, min(1.0, sweat_scalar)) * 4))
        
        # Get pose-specific config
        sweat_config = POSE_SWEAT_CONFIG.get(pose, POSE_SWEAT_CONFIG.get("stand_backfacing", {}))
        fold_config = POSE_FOLD_CONFIG.get(pose, {})
        sources = sweat_config.get("sources", []) or []

        dt_est = max(0.01, min(0.10, getattr(self, "_last_dt", 1.0 / 30.0)))

        # ═══════════════════════════════════════════════════════════════════
        # HUMIDITY SHEEN (thin film)
        # A clinging gloss that builds before runoff. Not an "aura"—it's on-skin.
        # ═══════════════════════════════════════════════════════════════════
        zones = sweat_config.get("humidity_zones")
        if not zones:
            # Derive small zones from sweat sources (works for all poses automatically)
            zones = []
            for s in sweat_config.get("sources", []):
                sy = float(s.get("y", 0.0))
                rx = 2.0 if sy < -10 else 3.0
                ry = 2.0 if sy < -10 else 3.0
                zones.append({
                    "cx": float(s.get("x", 0.0)),
                    "cy": sy,
                    "rx": rx,
                    "ry": ry,
                    "rate": max(0.15, float(s.get("rate", 0.25))),
                })

        # Deposit a few film points per frame (scaled by dt for stable feel across FPS)
        if sweat_scalar > 0.02 and zones:
            for z in zones:
                zr = float(z.get("rate", 0.25))
                deposits = zr * (0.20 + 1.40 * (sweat_scalar ** 1.6)) * 2.2 * dt_est
                budget = deposits
                while budget > 0.0:
                    if self._rng.random() < min(1.0, budget):
                        cx0, cy0 = float(z.get("cx", 0.0)), float(z.get("cy", 0.0))
                        rx0, ry0 = float(z.get("rx", 3.0)), float(z.get("ry", 2.0))
                        # Sample inside an ellipse.
                        ang = self._rng.random() * 6.2831853
                        rr = math.sqrt(self._rng.random())
                        sx = cx0 + math.cos(ang) * rx0 * rr
                        sy = cy0 + math.sin(ang) * ry0 * rr
                        key = (int(round(sx)), int(round(sy)))

                        add = (0.05 + 0.20 * sweat_scalar) * (0.60 + 0.40 * self._rng.random())
                        self.film[key] = min(1.0, self.film.get(key, 0.0) + add)

                        # At higher saturation, occasionally seed a tiny amount of runoff.
                        if self.film[key] > 0.55 and sweat_scalar > 0.55 and self._rng.random() < 0.06 * sweat_scalar:
                            mkey = (key[0] + self._rng.choice([0, 0, -1, 1]), key[1] + 1)
                            self.moisture[mkey] = min(1.0, self.moisture.get(mkey, 0.0) + 0.10 * sweat_scalar)
                    budget -= 1.0

        # Render thin film sheen (cyan, mostly dim; occasional bright glints)
        if self.film:
            try:
                items = sorted(self.film.items(), key=lambda kv: kv[1])
                for (fx, fy), val in items:
                    if val < 0.03:
                        continue
                    px = fig_cx + int(fx)
                    py = fig_cy + int(fy)
                    if 0 <= px < w - 1 and 0 <= py < h - 1:
                        if val < 0.10:
                            ch = '.'
                            attr = curses.A_DIM | curses.color_pair(3)
                        elif val < 0.22:
                            ch = ':'
                            attr = curses.A_DIM | curses.color_pair(3)
                        elif val < 0.40:
                            ch = ';'
                            attr = curses.A_NORMAL | curses.color_pair(3)
                        else:
                            # Glossy highlight / bead
                            ch = "'" if self._rng.random() < 0.45 else "°"
                            base_col = curses.color_pair(2) if self._rng.random() < 0.35 else curses.color_pair(3)
                            attr = curses.A_BOLD | base_col
                        scr.addch(py, px, ch, attr)
            except:
                pass
        
        # Track pose changes for drip continuity
        if pose != self.last_pose:
            self.last_pose = pose
            # Don't clear drips - they continue falling during pose change
# Render sweat source markers (debug)
        if DEBUG_SWEAT_SOURCES and sweat_config.get('sources'):
            for s in sweat_config.get('sources', []):
                px = fig_cx + int(s['x'])
                py = fig_cy + int(s['y'])
                if 0 <= px < w - 1 and 0 <= py < h - 1:
                    try:
                        scr.addch(py, px, 'x', curses.A_DIM)
                    except:
                        pass
            # Mark first few drip path points too
            for pinfo in sweat_config.get('drip_paths', [])[:3]:
                for dx, dy in pinfo.get('path', [])[:4]:
                    px = fig_cx + int(dx)
                    py = fig_cy + int(dy)
                    if 0 <= px < w - 1 and 0 <= py < h - 1:
                        try:
                            scr.addch(py, px, '·', curses.A_DIM)
                        except:
                            pass

        # ═══════════════════════════════════════════════════════════════════
        # SPAWN NEW SWEAT DRIPS from sources
        # ═══════════════════════════════════════════════════════════════════
        if sweat_scalar > 0.04:
            for source in sources:
                # Spawn rate based on sweat level and source rate
                spawn_rate = float(source.get("rate", 0.25)) * (0.12 + 1.10 * (sweat_scalar ** 2.2))
                spawn_chance = spawn_rate * dt_est
                if self._rng.random() < spawn_chance:
                    self.active_drips.append({
                        'x': source["x"] + random.uniform(-0.5, 0.5),
                        'y': source["y"],
                        'vy': random.uniform(0.3, 0.8),
                        'age': 0,
                        'lifespan': random.uniform(2.0, 4.0),
                        'source': source["name"],
                    })
        

        # AMBIENT SHEEN (humidity film): deposit subtle moisture near sources even when drops aren't falling.
        # This reads as warm skin + humidity rather than constant pouring.
        if sweat_scalar > 0.10 and sources:
            for s in sources:
                if random.random() < 0.10 * sweat_scalar:
                    # Small clustered speckle around the source point
                    for _ in range(2):
                        dx = int(random.choice([-1, 0, 0, 1]))
                        dy = int(random.choice([0, 0, 1]))
                        key = (int(s['x']) + dx, int(s['y']) + dy)
                        self.moisture[key] = min(1.0, self.moisture.get(key, 0.0) + 0.06 * sweat_scalar)

        # ═══════════════════════════════════════════════════════════════════
        # RENDER ACTIVE SWEAT DRIPS
        # ═══════════════════════════════════════════════════════════════════
        for drip in self.active_drips:
            px = fig_cx + int(drip['x'])
            py = fig_cy + int(drip['y'])
            
            if 0 <= px < w - 1 and 0 <= py < h - 1:
                try:
                    # Drip char varies by age (bead -> slide -> fading)
                    age_ratio = drip['age'] / drip['lifespan']
                    if age_ratio < 0.22:
                        char = "'"
                        attr = curses.A_BOLD
                    elif age_ratio < 0.55:
                        char = ","
                        attr = curses.A_NORMAL
                    else:
                        char = "·"
                        attr = curses.A_DIM

                    # Sweat is cyan by default; highlights can pop slightly.
                    scr.addch(py, px, char, attr | curses.color_pair(3))
                    # Deposit moisture at this drip location (figure-local coords)
                    key = (int(drip['x']), int(drip['y']))
                    self.moisture[key] = min(1.0, self.moisture.get(key, 0.0) + (0.10 + 0.20 * (1.0 - age_ratio)) * max(0.0, sweat_scalar))
                except:
                    pass
        
        # ═══════════════════════════════════════════════════════════════════
        # RENDER DRIP PATH TRACES (sweat that's already dripped)
        # Only show at higher sweat levels
        # ═══════════════════════════════════════════════════════════════════
        if sweat_level >= 2:
            drip_paths = sweat_config.get("drip_paths", [])
            # Pooling points (defaults to ends of first drip paths) for runoff illusion
            pools = sweat_config.get('pools')
            if not pools and drip_paths:
                pools = [(pi.get('path', [])[-1][0], pi.get('path', [])[-1][1]) for pi in drip_paths[:2] if isinstance(pi, dict) and pi.get('path')]
            if pools and sweat_scalar > 0.55:
                # subtle: occasional pooling growth, not a new mechanic
                if self._rng.random() < 0.06 * sweat_scalar:
                    px, py = random.choice(pools)
                    key = (int(px), int(py))
                    self.moisture[key] = min(1.0, self.moisture.get(key, 0.0) + 0.12 * sweat_scalar)

            for path_info in drip_paths:
                path = path_info.get("path", [])
                # Show more of path at higher levels
                show_count = min(len(path), sweat_level)
                for i, (dx, dy) in enumerate(path[:show_count]):
                    if self._rng.random() < 0.35 + sweat_level * 0.08:
                        px = fig_cx + dx
                        py = fig_cy + dy
                        if 0 <= px < w - 1 and 0 <= py < h - 1:
                            try:
                                scr.addch(py, px, "·", curses.A_DIM | curses.color_pair(3))
                            except:
                                pass
        
        # ═══════════════════════════════════════════════════════════════════
        # ═══════════════════════════════════════════════════════════════════
        # RENDER MOISTURE MAP (pooling + runoff illusion, subtle cell shading)
        # ═══════════════════════════════════════════════════════════════════
        if self.moisture:
            try:
                items = sorted(self.moisture.items(), key=lambda kv: kv[1])
                for (mx, my), val in items:
                    px = fig_cx + int(mx)
                    py = fig_cy + int(my)
                    if 0 <= px < w - 1 and 0 <= py < h - 1:
                        # Moisture = heavier wetness/runoff. Cyan dim, with rare white glints.
                        if val < 0.10:
                            ch = '.'
                            attr = curses.A_DIM | curses.color_pair(3)
                        elif val < 0.22:
                            ch = ':'
                            attr = curses.A_DIM | curses.color_pair(3)
                        elif val < 0.38:
                            ch = ';'
                            attr = curses.A_NORMAL | curses.color_pair(3)
                        else:
                            ch = 'o' if self._rng.random() < 0.18 else ';'
                            glint = (curses.color_pair(2) if self._rng.random() < 0.20 else curses.color_pair(3))
                            attr = curses.A_BOLD | glint
                        scr.addch(py, px, ch, attr)
            except:
                pass

        # RENDER BODY FOLDS
        # Always visible - these are anatomical features
        # ═══════════════════════════════════════════════════════════════════
        folds = fold_config.get("folds", [])
        for fold in folds:
            px = fig_cx + fold["x"]
            py = fig_cy + fold["y"]
            
            if 0 <= px < w - 1 and 0 <= py < h - 1:
                try:
                    char = FOLD_CHARS.get(fold["type"], "_")
                    # Folds are subtle - always dim
                    scr.addch(py, px, char, curses.A_DIM)
                except:
                    pass

# Which particles to spawn based on combo/intensity
DRIP_PROFILES = {
    "calm": {"type": "sweat", "rate": 0.1, "speed": 0.5},
    "warming": {"type": "sweat", "rate": 0.2, "speed": 0.6},
    "building": {"type": "spark", "rate": 0.3, "speed": 0.7},
    "intense": {"type": "steam", "rate": 0.5, "speed": 0.8},
    "peak": {"type": "heart", "rate": 0.7, "speed": 1.0},
    "combo_reward": {"type": "heart", "rate": 1.0, "speed": 1.2},
}

@dataclass
class DripParticle:
    """A particle dripping from sprites to highway"""
    x: float
    y: float
    char: str
    speed: float
    color: int
    life: float = 1.0

class ParticleDrip:
    """Manages particles dripping from sprites onto highway"""
    
    def __init__(self):
        self.particles: List[DripParticle] = []
        self.spawn_timer = 0.0
        self.current_profile = DRIP_PROFILES["calm"]
        self.beat_sync = 0.0
    
    def set_profile(self, intensity: float, combo: int):
        """Update drip profile based on game state"""
        if combo >= 10:
            self.current_profile = DRIP_PROFILES["combo_reward"]
        elif intensity >= 80:
            self.current_profile = DRIP_PROFILES["peak"]
        elif intensity >= 60:
            self.current_profile = DRIP_PROFILES["intense"]
        elif intensity >= 40:
            self.current_profile = DRIP_PROFILES["building"]
        elif intensity >= 20:
            self.current_profile = DRIP_PROFILES["warming"]
        else:
            self.current_profile = DRIP_PROFILES["calm"]
    
    def spawn_at(self, x: int, y: int, on_beat: bool = False):
        """Spawn a particle at position"""
        drip_type = self.current_profile["type"]
        chars = DRIP_CHARS.get(drip_type, DRIP_CHARS["sweat"])
        char = random.choice(chars)
        
        # Color based on type
        color = {
            "sweat": 3,   # Cyan
            "heart": 6,   # Red/Magenta
            "spark": 1,   # Yellow
            "steam": 2,   # White
            "intense": 6, # Red
        }.get(drip_type, 2)
        
        # On beat = faster, bigger
        speed = self.current_profile["speed"]
        if on_beat:
            speed *= 1.5
        
        self.particles.append(DripParticle(
            x=x + random.uniform(-1, 1),
            y=y,
            char=char,
            speed=speed * 8,  # Pixels per second
            color=color,
            life=1.0
        ))
    
    def update(self, dt: float, sprite_y: int, sprite_x_range: Tuple[int, int], 
               bpm: float, beat_phase: float):
        """Update particles and spawn new ones"""
        # Check for beat sync
        beat_period = 60.0 / bpm
        old_beat = int(self.beat_sync / beat_period)
        self.beat_sync += dt
        new_beat = int(self.beat_sync / beat_period)
        on_beat = new_beat > old_beat
        
        # Spawn based on rate and beat
        self.spawn_timer -= dt
        if self.spawn_timer <= 0:
            spawn_chance = self.current_profile["rate"]
            if on_beat:
                spawn_chance *= 2  # More likely on beat
            
            if random.random() < spawn_chance:
                x = random.randint(sprite_x_range[0], sprite_x_range[1])
                self.spawn_at(x, sprite_y, on_beat)
            
            self.spawn_timer = 0.1  # Check every 100ms
        
        # Update existing particles
        for p in self.particles:
            p.y += p.speed * dt
            p.life -= dt * 0.5
        
        # Remove dead particles
        self.particles = [p for p in self.particles if p.life > 0 and p.y < sprite_y + 15]
    
    def render(self, scr, highway_top: int, highway_bottom: int):
        """Render particles falling toward highway"""
        for p in self.particles:
            if highway_top <= int(p.y) <= highway_bottom:
                try:
                    attr = curses.color_pair(p.color)
                    if p.life < 0.3:
                        attr |= curses.A_DIM
                    scr.addch(int(p.y), int(p.x), p.char, attr)
                except:
                    pass

@dataclass
class SpriteState:
    """Compact sprite state with slip meter and pose mirroring"""
    pen_state: PenState = field(default=PenState.INTRO)
    intro_phase: int = 0  # 0=stand_back, 1=front_presence, 2=approaching
    approach_t: float = 0.0
    
    grip: float = 3.0
    slip_timer: float = 0.0
    reentry_timer: float = 0.0
    wrong_timer: float = 0.0
    buck_combo: int = 0
    stuck_turns: int = 0
    launched_timer: float = 0.0
    afterglow_timer: float = 0.0
    
    ogre_face: str = "calm"
    her_face: str = "flow"
    her_butt: str = "normal"
    jiggle_t: float = 0.0
    jiggle_amp: float = 0.0
    beat_idx: int = 0
    shake_t: float = 0.0
    shake_amp: float = 0.0
    buck_phase: float = 0.0
    
    particles: List[dict] = field(default_factory=list)
    tempo_mod: float = 1.0
    flash_t: float = 0.0
    flash_color: int = 0
    burst_notes: List[dict] = field(default_factory=list)
    
    # Pose mirroring
    current_lightmap_pose: str = "stand_backfacing"
    sprite_x_center: int = 0  # Last rendered center for particle spawning
    
    def mirror_lightmap_pose(self, pose: str):
        """Update sprite configuration to mirror lightmap pose"""
        self.current_lightmap_pose = pose
        
        # Update face/expression based on pose
        pose_expressions = {
            "stand_backfacing": ("calm", "flow"),
            "front_presence": ("calm", "brat"),
            "coy_cheek": ("hype", "flow"),
            "face": ("sync", "heart"),
            "downward": ("hype", "surge"),
            "squat": ("hype", "surge"),
            "angled_collapse": ("relief", "relief"),
            "strut": ("shock", "wobble"),
            "laying_smile": ("relief", "relief"),
        }
        
        if pose in pose_expressions:
            ogre_exp, her_exp = pose_expressions[pose]
            # Only override if not in a special state
            if self.pen_state == PenState.NORMAL:
                self.ogre_face = ogre_exp
                self.her_face = her_exp
    
    def get_sprite_config(self) -> dict:
        """Get sprite positioning based on current lightmap pose"""
        return POSE_SPRITE_CONFIG.get(
            self.current_lightmap_pose, 
            POSE_SPRITE_CONFIG["coy_cheek"]
        )
    
    def get_lightmap_pose(self, mode: str, intensity: float) -> str:
        """Get appropriate lightmap pose for current state"""
        if self.pen_state == PenState.INTRO:
            if self.intro_phase == 0:
                return "stand_backfacing"
            elif self.intro_phase == 1:
                return "front_presence"
            else:
                return "coy_cheek"
        elif self.pen_state == PenState.SLIPPING:
            return "strut"
        elif self.pen_state == PenState.REENTERING:
            return "strut"
        elif self.pen_state in (PenState.WRONG, PenState.BUCKING, PenState.STUCK):
            return "squat"
        elif self.pen_state == PenState.LAUNCHED:
            return "strut"
        elif self.pen_state == PenState.AFTERGLOW:
            return "laying_smile"
        else:
            return get_mode_pose(mode, intensity)
    
    def should_dim_lightmap(self) -> bool:
        """Should lightmap be dimmed?"""
        return self.pen_state in (PenState.SLIPPING, PenState.STUCK)
    
    def update(self, dt: float, bpm: float = 80):
        beat_len = 60.0 / (bpm * self.tempo_mod)
        self.beat_idx = int(time.time() / beat_len)
        
        # Intro sequence
        if self.pen_state == PenState.INTRO:
            self.approach_t += dt
            if self.intro_phase == 0 and self.approach_t >= 2.0:
                self.intro_phase = 1
                self.approach_t = 0
            elif self.intro_phase == 1 and self.approach_t >= 2.0:
                self.intro_phase = 2
                self.pen_state = PenState.APPROACHING
                self.approach_t = 0
        
        # Approaching
        elif self.pen_state == PenState.APPROACHING:
            self.approach_t += dt
            if self.approach_t >= 2.0:
                self.pen_state = PenState.NORMAL
                self.ogre_face = "hype"
                self.her_face = "flow"
        
        # Slip cooldown
        elif self.pen_state == PenState.SLIPPING:
            self.slip_timer -= dt
            if self.slip_timer <= 0:
                self.pen_state = PenState.REENTERING
                self.reentry_timer = 0.5
        
        # Re-entry
        elif self.pen_state == PenState.REENTERING:
            self.reentry_timer -= dt
            if self.reentry_timer <= 0:
                self.pen_state = PenState.NORMAL
                self.grip = 3.0
                self.ogre_face = "hype"
                self.her_face = "flow"
        
        # Wrong hole
        elif self.pen_state == PenState.WRONG:
            self.wrong_timer -= dt
            if self.wrong_timer <= 0:
                self.pen_state = PenState.BUCKING
                self.buck_combo = 0
                self.tempo_mod = 1.3
        
        # Bucking
        elif self.pen_state == PenState.BUCKING:
            self.buck_phase += dt * 10
            self.jiggle_amp = 2.0
            self.jiggle_t = 1.0
        
        # Launched
        elif self.pen_state == PenState.LAUNCHED:
            self.launched_timer -= dt
            if self.launched_timer <= 0:
                self.pen_state = PenState.SLIPPING
                self.slip_timer = 1.5
                self.ogre_face = "calm"
        
        # Afterglow
        elif self.pen_state == PenState.AFTERGLOW:
            self.afterglow_timer -= dt
            # Stay in afterglow until manually changed
        
        # Jiggle decay
        if self.pen_state not in (PenState.BUCKING,):
            if self.jiggle_t > 0:
                self.jiggle_t = max(0, self.jiggle_t - dt)
            else:
                self.jiggle_amp *= 0.85
        
        # Butt animation
        if self.jiggle_amp > 1.0:
            self.her_butt = "jiggle_l" if self.beat_idx % 2 == 0 else "jiggle_r"
        elif self.pen_state in (PenState.WRONG, PenState.BUCKING, PenState.STUCK):
            self.her_butt = "panic"
        else:
            self.her_butt = "normal"
        
        # Shake/flash decay
        self.shake_t = max(0, self.shake_t - dt * 3) if self.shake_t > 0 else 0
        if self.shake_t <= 0: self.shake_amp = 0
        self.flash_t = max(0, self.flash_t - dt * 4) if self.flash_t > 0 else 0
        
        # Particles
        alive = []
        for p in self.particles:
            p["x"] += p["vx"] * dt
            p["y"] += p["vy"] * dt
            p["vy"] += p.get("gravity", 0) * dt
            p["life"] -= dt
            if p["life"] > 0: alive.append(p)
        self.particles = alive
        
        # Burst notes
        alive_burst = []
        for b in self.burst_notes:
            b["x"] += b["vx"] * dt
            b["y"] += b["vy"] * dt
            b["life"] -= dt
            if b["life"] > 0: alive_burst.append(b)
        self.burst_notes = alive_burst
    
    def trigger_hit(self, lane: str, quality: str) -> Optional[str]:
        event = None
        
        if self.pen_state == PenState.BUCKING:
            if quality in ("perfect", "great", "good"):
                self.buck_combo += 1
                if self.buck_combo >= 5:
                    self._trigger_escape()
                    event = "escaped"
            else:
                self.pen_state = PenState.STUCK
                self.stuck_turns = 3
                self.tempo_mod = 1.0
                self.ogre_face = "panic"
                self.her_face = "stuck"
                event = "stuck"
            return event
        
        if self.pen_state == PenState.STUCK:
            self.stuck_turns -= 1
            if self.stuck_turns <= 0:
                self.pen_state = PenState.BUCKING
                self.buck_combo = 0
                self.tempo_mod = 1.3
            return "stuck"
        
        if self.pen_state in (PenState.SLIPPING, PenState.REENTERING, PenState.WRONG, 
                              PenState.LAUNCHED, PenState.INTRO, PenState.AFTERGLOW):
            return "cooldown"
        
        if self.pen_state == PenState.APPROACHING:
            return None
        
        # Normal gameplay - restore grip
        if quality == "perfect":
            self.grip = min(3.0, self.grip + 0.5)
        elif quality == "great":
            self.grip = min(3.0, self.grip + 0.25)
        elif quality == "good":
            self.grip = min(3.0, self.grip + 0.1)
        
        # Animations
        if lane == "A":
            self.jiggle_t = 0.5
            self.jiggle_amp = 1.8 if quality == "perfect" else 1.2
            self.her_face = "surge" if quality == "perfect" else "brat"
            self.ogre_face = "hype"
        elif lane == "S":
            self.jiggle_t = 0.3
            self.jiggle_amp = 0.8
            self.her_face = "flow"
        elif lane == "B":
            self.jiggle_t = 0.4
            self.jiggle_amp = 1.5
            self.her_face = "flow"
            self.ogre_face = "hype"
        elif lane == "SPACE":
            self.her_face = "heart"
            self.ogre_face = "sync"
            self.shake_t = 0.2
            self.shake_amp = 0.5
        
        return event
    
    def trigger_miss(self, lane: str, note_positions: List[Tuple[int, int]] = None) -> Optional[str]:
        event = None
        
        if self.pen_state == PenState.BUCKING:
            self.pen_state = PenState.STUCK
            self.stuck_turns = 3
            self.tempo_mod = 1.0
            self.ogre_face = "panic"
            self.her_face = "stuck"
            return "stuck"
        
        if self.pen_state != PenState.NORMAL:
            return None
        
        self.grip -= 1.0
        self.ogre_face = "shock"
        self.her_face = "wobble"
        
        if self.grip <= 0:
            self._trigger_slip(note_positions)
            event = "slipped"
        
        return event
    
    def trigger_climax(self):
        """Trigger climax → afterglow sequence"""
        self.pen_state = PenState.AFTERGLOW
        self.afterglow_timer = 10.0
        self.ogre_face = "relief"
        self.her_face = "relief"
    
    def _trigger_slip(self, note_positions=None):
        self.pen_state = PenState.SLIPPING
        self.slip_timer = 2.5
        self.grip = 0
        self.ogre_face = "shock"
        self.her_face = "wobble"
        self.flash_t = 1.0
        self.flash_color = 6
        self.tempo_mod = 1.0
        
        if note_positions:
            for x, y in note_positions[:5]:
                for _ in range(3):
                    self.burst_notes.append({
                        "x": float(x), "y": float(y),
                        "vx": random.uniform(-20, 20),
                        "vy": random.uniform(-15, 5),
                        "char": random.choice(["●", "○", "*"]),
                        "life": 1.0,
                    })
    
    def _trigger_wrong_hole(self):
        self.pen_state = PenState.WRONG
        self.wrong_timer = 0.8
        self.ogre_face = "panic"
        self.her_face = "panic"
        self.shake_t = 0.8
        self.shake_amp = 3.0
        self.flash_t = 0.5
        self.flash_color = 6
    
    def _trigger_escape(self):
        self.pen_state = PenState.LAUNCHED
        self.launched_timer = 1.5
        self.tempo_mod = 1.0
        self.ogre_face = "relief"
        self.her_face = "relief"
        self.shake_t = 0.5
        self.shake_amp = 2.0
        
        for _ in range(20):
            self.particles.append({
                "x": 0, "y": 0,
                "vx": random.uniform(-8, -2),
                "vy": random.uniform(-4, 4),
                "gravity": -2,
                "char": random.choice(["~", "≈", "°", "*", "P", "F", "T"]),
                "life": 2.0,
            })
    
    def get_grip_display(self) -> str:
        hearts = int(self.grip)
        empties = 3 - hearts
        partial = self.grip - hearts
        s = "["
        s += "♥" * hearts
        if partial > 0.5 and empties > 0:
            s += "◐"; empties -= 1
        elif partial > 0 and empties > 0:
            s += "◔"; empties -= 1
        s += "○" * empties
        s += "]"
        return s
    
    def render(self, scr, base_y: int, width: int):
        h, w = scr.getmaxyx()
        cx = w // 2
        
        shake_x = int(random.uniform(-1, 1) * self.shake_amp) if self.shake_t > 0 else 0
        shake_y = int(random.uniform(-1, 1) * self.shake_amp * 0.5) if self.shake_t > 0 else 0
        
        # Screen flash
        if self.flash_t > 0:
            try:
                flash_attr = curses.color_pair(self.flash_color) | curses.A_REVERSE
                for row in range(h):
                    if random.random() < self.flash_t * 0.3:
                        scr.addstr(row, 0, " " * (w-1), flash_attr)
            except: pass
        
        # Get pose-based positioning
        config = self.get_sprite_config()
        
        # Positions based on state (with pose-based defaults)
        if self.pen_state == PenState.INTRO:
            ogre_x = cx - config["ogre_distance"]
            her_x = cx
            connected = False
        elif self.pen_state == PenState.APPROACHING:
            progress = min(1.0, self.approach_t / 2.0)
            ogre_x = cx - 25 + int(progress * 3)
            her_x = cx - int(progress * 5)
            connected = False
        elif self.pen_state in (PenState.SLIPPING, PenState.REENTERING, PenState.LAUNCHED):
            ogre_x = cx - 30
            her_x = cx
            connected = False
        else:
            # Use pose-based config for normal gameplay
            ogre_x = cx - config["ogre_distance"] - 5
            her_x = cx - 5
            connected = config["connected"]
        
        # Apply pose-based y offset
        y_offset = config.get("her_y_offset", 0)
        
        ogre_x += shake_x
        her_x += shake_x
        y = base_y + shake_y + y_offset
        
        # Track sprite center for particle spawning
        self.sprite_x_center = her_x + 10
        
        if self.pen_state == PenState.BUCKING:
            her_x += int(math.sin(self.buck_phase) * 3)
        
        # Render ogre
        try:
            scr.addstr(y - 2, ogre_x + 2, OGRE_HELMET, curses.A_BOLD)
            face = OGRE_FACES.get(self.ogre_face, OGRE_FACES["calm"])
            scr.addstr(y - 1, ogre_x + 1, face)
            if connected and self.pen_state == PenState.NORMAL:
                scr.addstr(y, ogre_x, OGRE_TAIL)
            elif self.pen_state in (PenState.WRONG, PenState.BUCKING, PenState.STUCK):
                scr.addstr(y, ogre_x, "----=====>")
            else:
                scr.addstr(y, ogre_x, "----===>")
        except: pass
        
        # Render her
        butt = HER_BUTT.get(self.her_butt, HER_BUTT["normal"])
        face = HER_FACES.get(self.her_face, HER_FACES["flow"])
        back = HER_BACK_BUCK if self.pen_state == PenState.BUCKING else HER_BACK
        
        jiggle_off = int(self.jiggle_amp * (1 if self.beat_idx % 2 == 0 else -1)) if self.jiggle_t > 0 else 0
        
        try:
            top_line = f"{butt}{back} {face}"
            scr.addstr(y - 1 + jiggle_off, her_x, top_line, curses.color_pair(2))
            
            if self.pen_state == PenState.NORMAL:
                rear = HER_REAR_FILLED
            elif self.pen_state in (PenState.WRONG, PenState.BUCKING):
                rear = HER_REAR_WRONG
            elif self.pen_state == PenState.STUCK:
                rear = HER_REAR_STUCK
            else:
                rear = HER_REAR_OPEN
            
            if self.pen_state in (PenState.WRONG, PenState.BUCKING, PenState.STUCK):
                scr.addstr(y + jiggle_off, her_x, HER_LEGS)
                scr.addstr(y + jiggle_off, her_x + len(HER_LEGS), rear, curses.color_pair(6) | curses.A_BOLD)
                scr.addstr(y + jiggle_off, her_x + len(HER_LEGS) + len(rear), HER_FRONT)
            else:
                scr.addstr(y + jiggle_off, her_x, f"{HER_LEGS}{rear}{HER_FRONT}")
        except: pass
        
        # Baseline. Keep it out of squat: it reads as a black bar through the
        # central lightmap silhouette when the compact sprite jiggles.
        if self.current_lightmap_pose != "squat":
            try:
                scr.addstr(y + 1, ogre_x - 2, "─" * (her_x - ogre_x + 30), curses.A_DIM)
            except: pass
        # State indicators
        if self.pen_state == PenState.SLIPPING:
            try:
                remaining = max(0, self.slip_timer)
                bar_w = 15
                filled = int((remaining / 2.5) * bar_w)
                text = f"SLIPPED! [{('█' * filled) + ('░' * (bar_w - filled))}]"
                scr.addstr(y - 3, cx - len(text) // 2, text, curses.color_pair(6) | curses.A_BOLD)
            except: pass
        elif self.pen_state == PenState.REENTERING:
            try:
                scr.addstr(y - 3, cx - 7, "Re-entering...", curses.color_pair(4))
            except: pass
        elif self.pen_state == PenState.WRONG:
            try:
                scr.addstr(y - 3, cx - 6, "WRONG HOLE!", curses.color_pair(6) | curses.A_BOLD | curses.A_BLINK)
            except: pass
        elif self.pen_state == PenState.BUCKING:
            try:
                prog = self.buck_combo / 5
                bar_w = 10
                filled = int(prog * bar_w)
                text = f"ESCAPE! [{('█' * filled) + ('░' * (bar_w - filled))}] {self.buck_combo}/5"
                scr.addstr(y - 3, cx - len(text) // 2, text, curses.color_pair(6) | curses.A_BOLD)
            except: pass
        elif self.pen_state == PenState.STUCK:
            try:
                scr.addstr(y - 3, cx - 7, f"STUCK! ({self.stuck_turns})", curses.color_pair(6) | curses.A_BOLD)
            except: pass
        elif self.pen_state == PenState.LAUNCHED:
            try:
                scr.addstr(y - 3, cx - 3, "PFFFT!", curses.color_pair(4) | curses.A_BOLD)
            except: pass
        elif self.pen_state == PenState.AFTERGLOW:
            try:
                scr.addstr(y - 3, cx - 5, "~ afterglow ~", curses.color_pair(5) | curses.A_DIM)
            except: pass
        
        # Particles
        particle_base_x, particle_base_y = her_x, y
        for p in self.particles:
            px = int(particle_base_x + p["x"])
            py = int(particle_base_y + p["y"])
            if 0 <= py < h and 0 <= px < w - 1 and p["life"] > 0.2:
                try:
                    scr.addstr(py, px, p["char"], curses.A_DIM)
                except: pass
        
        # Burst notes
        for b in self.burst_notes:
            if 0 <= int(b["y"]) < h and 0 <= int(b["x"]) < w - 1 and b["life"] > 0.2:
                try:
                    scr.addstr(int(b["y"]), int(b["x"]), b["char"], curses.color_pair(6))
                except: pass

# ═══════════════════════════════════════════════════════════════════════════════
#                              DIALOGUE SYSTEM (COMPLETE)
#                              With pose-aware interlude selection
# ═══════════════════════════════════════════════════════════════════════════════

# === INTERLUDE POSE REQUIREMENTS ===
# Some interludes require specific poses or forbid others

INTERLUDE_POSE_DATA = {
    # Face-required interludes (eye contact, intimacy)
    "face_required": {
        "requires_face": True,
        "preferred_poses": ["face", "coy_cheek", "front_presence", "downward"],
    },
    # Back-ok interludes (physical, less verbal)
    "back_ok": {
        "requires_face": False,
        "preferred_poses": ["squat", "stand_backfacing", "downward"],
    },
    # Afterglow interludes (post-intensity)
    "afterglow": {
        "requires_face": True,
        "preferred_poses": ["laying_smile", "angled_collapse"],
    },
    # Active/challenging interludes
    "active": {
        "requires_face": True,
        "preferred_poses": ["front_presence", "strut", "coy_cheek"],
    },
}


def select_interlude_for_pose(pool: List, current_pose: str, mode: str) -> List:
    """
    Select an interlude that works with the current pose.
    If current pose forbids the interlude content, triggers pose change.
    """
    pose_ctx = POSE_CONTEXT.get(current_pose, {})
    can_see_face = pose_ctx.get("can_see_face", True)
    
    # For face-hidden poses, prefer interludes without eye contact dialogue
    face_dialogue_phrases = ["look at me", "eyes", "see you", "see your face", "watching you"]
    
    # Filter interludes
    suitable = []
    for interlude in pool:
        # Check if any line requires face visibility
        needs_face = False
        for speaker, line in interlude:
            line_lower = str(line).lower()
            if any(phrase in line_lower for phrase in face_dialogue_phrases):
                needs_face = True
                break
        
        if needs_face and not can_see_face:
            continue  # Skip this interlude
        
        suitable.append(interlude)
    
