# Track which snippets have been shown to avoid repeats
STORY_SNIPPET_SHOWN = set()

def get_random_story_snippet():
    """Get a random story snippet that hasn't been shown yet"""
    global STORY_SNIPPET_SHOWN
    available = [i for i in range(len(STORY_SNIPPET_LIBRARY)) if i not in STORY_SNIPPET_SHOWN]
    if not available:
        # Reset if all shown
        STORY_SNIPPET_SHOWN = set()
        available = list(range(len(STORY_SNIPPET_LIBRARY)))
    
    idx = random.choice(available)
    STORY_SNIPPET_SHOWN.add(idx)
    return STORY_SNIPPET_LIBRARY[idx]

