# Intensity tier thresholds
def get_intensity_tier(intensity: float) -> str:
    if intensity < 40:
        return "building"
    elif intensity < 75:
        return "peak"
    else:
        return "release"

# New dialogue class with decision tree
class AuthoredDialogue:
    """Decision-tree dialogue system with authored exchanges - LEAKS INTEGRATED INTO SPEECH"""
    
    def __init__(self):
        self.fiend_line = ""
        self.bird_line = ""  # Now contains integrated leaks: "Oiii~— text *squirm*"
        self.inner_line = ""

        # Voice commit tracking (prevents re-speak spam from redraws)
        self._voice_seq = {"FIEND": 0, "BIRDSONG": 0, "NARRATOR": 0}
        self._last_voice_text = {"FIEND": "", "BIRDSONG": "", "NARRATOR": ""}
        
        # Legacy attributes (kept for compatibility)
        self.leak_line = ""
        self.leak_timer = 0.0
        
        # Track if current line has leaks
        self.has_leak = False
        
        self.fiend_timer = 0.0
        self.bird_timer = 0.0
        self.inner_timer = 0.0
        
        # Track state for decision tree
        self.last_combo = 0
        self.streak_before_miss = 0
        self.misses_in_row = 0
        self.milestone_shown = set()
        self.hits_since_miss = 0
        self.current_mode = "gentle"

        # Birdsong keystone: SYNC/attunement gate (0-100)
        self.sync_level = 0.0
        
        # Recent lines to avoid repetition
        self.recent_exchanges = []
        self.recent_miss = []
        
        # Reciprocity tracking - last displayed line for emotional contagion
        self.last_displayed = (None, None)  # (speaker, text)
        
        # Queued lines for reciprocity responses
        self.queued_lines: List[Tuple[str, str]] = []

        # OY/SURGE sentence-entry memory. Short-lived by design: the next few
        # rhythm dialogue beats should know Fiend entered Bird's sentence.
        self.last_oy_call = ""
        self.last_oy_match = ""
        self.last_oy_tier = 0
        self.last_oy_timestamp = 0.0
        self.recent_interrupt_count = 0
        self.oy_cascade_bias = ""
        self.oy_cascade_beats_remaining = 0
        
        # Unified dialogue engine for leakage + state tracking
        if UNIFIED_DIALOGUE_AVAILABLE:
            self.dialogue_engine = get_dialogue_engine()
        else:
            self.dialogue_engine = None
        
    # Contextual exchange picker (Cascade Intelligence)
    # Uses persistent theme/memory bias when available, otherwise defaults to random.
    def _pick_exchange(self, exchanges, intensity: float, trigger: str = ""):
        if not exchanges:
            return None
        try:
            if self.dialogue_engine and hasattr(self.dialogue_engine, "pick_exchange"):
                norm = intensity / 100.0 if intensity > 1.0 else float(intensity)
                try:
                    self.dialogue_engine.set_trigger_context(trigger)
                except Exception:
                    pass
                picked = self.dialogue_engine.pick_exchange(exchanges, intensity=norm, trigger=trigger)
                if picked:
                    return picked
        except Exception:
            pass
        return random.choice(exchanges)

        # ═══════════════════════════════════════════════════════════════════
        # CASCADE TRACKING REFERENCE
        # ═══════════════════════════════════════════════════════════════════
        self._cascade: Optional[DialogueCascade] = None
        self._cascade_context_getter = None  # Function to get context snapshot
        self._last_trigger_type = "automatic"
        self._last_trigger_source = ""
    
    def set_cascade(self, cascade: 'DialogueCascade', context_getter):
        """Wire cascade tracking into dialogue system."""
        self._cascade = cascade
        self._cascade_context_getter = context_getter
    
    def set_trigger_context(self, trigger_type: str, trigger_source: str):
        """Set context for next lines (hit/miss/milestone/etc)."""
        self._last_trigger_type = trigger_type
        self._last_trigger_source = trigger_source
    
    
    # ═══════════════════════════════════════════════════════════════════
    # GEN 9: HIT/MISS INTERJECTION PREFIXES (B_I_*)
    # ═══════════════════════════════════════════════════════════════════
    # These are short mid-action reactive fragments used to make hit/miss
    # exchanges feel immediate without forcing a full "sentence moment".
    _BIRDSONG_HIT_INTERJECTIONS = [
        "nngh—!",        # B_I_01
        "mmh—!",         # B_I_03
        "ah— wait—",     # B_I_06
        "hnn—",          # B_I_07
        "hah—! stop—",   # B_I_10
        "—! I—",         # B_I_11
        "nn— okay—",     # B_I_12
    ]
    _BIRDSONG_MISS_INTERJECTIONS = [
        "gah—!",         # B_I_02
        "wha—?!",        # B_I_04
        "hey—! no—",     # B_I_05
        "tch—!",         # B_I_08
        "pfft—!",        # B_I_09
    ]

    def _maybe_prefix_trigger_interjection(self, bird_text: str) -> str:
        """Optionally prefix Birdsong's line with a reactive interjection on hit/miss triggers."""
        if not bird_text:
            return bird_text

        t = (self._last_trigger_type or "").lower()
        src = (self._last_trigger_source or "").lower()

        # Only for immediate gameplay triggers
        if t not in ("hit", "miss"):
            return bird_text

        # Avoid double-interjection spam if the authored line already starts with a sound
        starter = bird_text.strip()
        already_soundy = starter.startswith(("Oy", "Mm", "Ghhh", "Hah", "Fie", "...", "HAH", "YES", "Nn", "Mmh", "Gah", "Wha", "Hey", "Tch", "Pfft"))
        already_dash = ("—" in starter[:6]) or ("~" in starter[:6])

        # Probability: misses get more "burst" than hits; perfect hits get a small boost
        if t == "miss":
            chance = 0.55
            pool = self._BIRDSONG_MISS_INTERJECTIONS
        else:
            chance = 0.30 if "perfect" in src else 0.22
            pool = self._BIRDSONG_HIT_INTERJECTIONS

        if already_soundy or already_dash:
            chance *= 0.35  # still possible, but rare

        if random.random() >= chance:
            return bird_text

        prefix = random.choice(pool).strip()
        return f"{prefix} {bird_text}"

    def _record_to_cascade(self, speaker: str, text: str):
        """Record a line to the cascade if wired."""
        if self._cascade and self._cascade_context_getter and text:
            try:
                ctx = self._cascade_context_getter()
                self._cascade.record_line(
                    speaker=speaker,
                    text=text,
                    trigger_type=self._last_trigger_type,
                    trigger_source=self._last_trigger_source,
                    context=ctx
                )
            except Exception:
                pass  # Don't break dialogue on tracking error
    
    def set_sync(self, sync_level: float):
        """Set Birdsong SYNC level (0-100). Used to gate deeper lines."""
        try:
            self.sync_level = float(sync_level)
        except Exception:
            self.sync_level = 0.0

    def set_mode(self, mode: str):
        """Set current gameplay mode for mode-specific dialogue"""
        self.current_mode = mode
    
    def get_birdsong_state(self) -> str:
        """Get current Birdsong emotional state from unified system"""
        if self.dialogue_engine:
            return self.dialogue_engine.get_birdsong_state()
        return "rambling"
    
    def get_suggested_fiend_tool(self) -> tuple:
        """Get suggested Fiend tool based on Birdsong's leaks"""
        if self.dialogue_engine:
            return self.dialogue_engine.get_suggested_fiend_tool()
        return ("observe", 0.5)

    def _clip_bird_line_for_oy(self, text: str) -> str:
        text = (text or "").strip()
        if not text:
            return ""
        if len(text) <= 26:
            return text.rstrip(".?!") + "-"
        return text[:26].rstrip(".?! -") + "-"

    def apply_oy_interruption(self, call: dict, match: str, tier: int, reaction: str, score: float):
        """Make SURGE feel like Fiend entering the current sentence."""
        call_id = str(call.get("id", "soften"))
        mouth = str(call.get("mouth", "OY"))

        if self.bird_line and self.bird_timer > 0:
            self.bird_line = self._clip_bird_line_for_oy(self.bird_line)
            self.bird_timer = max(self.bird_timer, 0.45)

        self.fiend_line = mouth
        self.fiend_timer = 1.15 + 0.15 * max(0, int(tier) - 1)
        self._last_trigger_type = "interjection"
        self._last_trigger_source = f"oy_{call_id}_{match}"
        self._record_to_cascade("FIEND", mouth)
        try:
            self._voice_any_line("FIEND", mouth)
        except Exception:
            pass

        if reaction:
            self.queued_lines.insert(0, ("BIRDSONG", str(reaction)))

        self.last_oy_call = call_id
        self.last_oy_match = str(match or "awkward")
        self.last_oy_tier = int(tier or 1)
        self.last_oy_timestamp = time.time()
        self.recent_interrupt_count = min(5, int(self.recent_interrupt_count or 0) + 1)
        self.oy_cascade_bias = f"{call_id}:{match}"
        self.oy_cascade_beats_remaining = {
            "perfect": 6,
            "good": 5,
            "awkward": 3,
            "bad": 4,
        }.get(str(match or "awkward"), 3)

    def _oy_bias_exchange(self, intensity: float):
        """Return a compact follow-up exchange while OY memory is still hot."""
        if self.oy_cascade_beats_remaining <= 0 or not self.last_oy_call:
            return None

        self.oy_cascade_beats_remaining -= 1
        if random.random() > 0.68:
            return None

        call_id = self.last_oy_call
        match = self.last_oy_match or "awkward"
        if match in ("perfect", "good"):
            pools = {
                "soften": [
                    ("...", "I was not hiding softness.", "Warm Wag keeps echoing under the line."),
                    ("Mm.", "...okay. I got quiet.", "The sentence melts instead of breaking."),
                ],
                "counter": [
                    ("Again.", "You are stealing my tempo.", "The banter catches sparks."),
                    ("OY OY.", "I did not flinch twice.", "She did."),
                ],
                "anchor": [
                    ("Stay on beat.", "...fine. I heard you.", "The line steadies."),
                    ("OY.", "Don't say it like a door closing.", "She comes back to center."),
                ],
                "focus": [
                    ("Eyes.", "I am looking.", "The stare lands."),
                    ("OY!", "...caught me.", "The sentence faces him."),
                ],
                "yield": [
                    ("Go on.", "...you want me to keep leading?", "Praise bait works."),
                    ("Mm.", "Okay. Listen then.", "Bird carries the next line softer."),
                ],
                "glint": [
                    ("Careful.", "You made that fun.", "Glint stays in the room."),
                    ("OYHUH.", "That laugh is trouble.", "The line smiles back."),
                ],
            }
        elif match == "bad":
            pools = {
                "soften": [("Too soft.", "My sentence.", "Bird takes the line back.")],
                "counter": [("Late.", "I keep the tempo.", "The comeback slips away.")],
                "anchor": [("No.", "You do not get the stop there.", "The hard edge misses.")],
                "focus": [("Look.", "Wrong moment.", "She turns the stare aside.")],
                "yield": [("Mm.", "You handed me that.", "Bird keeps the lead.")],
                "glint": [("Hah.", "Laugh after the joke lands.", "The grin arrives early.")],
            }
        else:
            pools = {
                call_id: [
                    ("Again?", "Cute timing. Not clean.", "The sentence wobbles."),
                    ("Mm.", "Almost.", "The read half-lands."),
                ]
            }

        pool = pools.get(call_id) or pools.get("soften") or pools.get("counter")
        return random.choice(pool) if pool else None
    
    def get_composure(self) -> float:
        """Get Birdsong's composure level"""
        if self.dialogue_engine:
            return self.dialogue_engine.get_composure()
        return 1.0
    
    def trigger_hit(self, lane: str, quality: str, intensity: float, combo: int):
        """Trigger dialogue for successful hit"""
        # Set cascade trigger context
        self.set_trigger_context("hit", f"{quality}_{lane}")
        
        tier = get_intensity_tier(intensity)
        self.hits_since_miss += 1
        
        # Check for combo milestones first (priority)
        for milestone, exchanges in sorted(COMBO_MILESTONES.items()):
            if combo >= milestone and milestone not in self.milestone_shown:
                self.milestone_shown.add(milestone)
                exchange = self._pick_exchange(exchanges, intensity, "milestone")
                self._set_exchange(exchange, duration_mult=1.5, always_inner=True, intensity=intensity)
                self.last_combo = combo
                self.misses_in_row = 0
                return
        
        # Perfect hit bonus (20% chance on perfect timing)
        if quality == "perfect" and random.random() < 0.2:
            exchange = self._pick_exchange(PERFECT_HIT_BONUS, intensity, "perfect")
            self._set_exchange(exchange, duration_mult=1.3, always_inner=True, intensity=intensity)
            self.last_combo = combo
            self.misses_in_row = 0
            return
        
        # Deep SYNC gate (Birdsong): high SYNC unlocks deeper lines
        try:
            sync = float(getattr(self, 'sync_level', 0.0))
        except Exception:
            sync = 0.0

        if sync >= 92.0 and random.random() < 0.10:
            exchange = self._pick_exchange(DEEP_SYNC_CORE, intensity, 'deep_sync_core')
            self._set_exchange(exchange, duration_mult=1.35, always_inner=True, intensity=intensity)
            self.last_combo = combo
            self.misses_in_row = 0
            return

        if sync >= 80.0 and random.random() < 0.16:
            exchange = self._pick_exchange(DEEP_SYNC_EXCHANGES, intensity, 'deep_sync')
            self._set_exchange(exchange, duration_mult=1.25, always_inner=True, intensity=intensity)
            self.last_combo = combo
            self.misses_in_row = 0
            return

        # OY memory: Fiend's entry biases a handful of subsequent rhythm beats.
        oy_exchange = self._oy_bias_exchange(intensity)
        if oy_exchange:
            self._set_exchange(oy_exchange, duration_mult=1.05, inner_chance=0.45, intensity=intensity)
            self.last_combo = combo
            self.misses_in_row = 0
            return

        # Mode-specific flavor (10% chance)
        if random.random() < 0.1:
            if self.current_mode == "gentle":
                exchange = self._pick_exchange(GENTLE_MODE_FLAVOR, intensity, "mode_gentle")
            elif self.current_mode == "rough":
                exchange = self._pick_exchange(ROUGH_MODE_FLAVOR, intensity, "mode_rough")
            else:
                exchange = None
            
            if exchange:
                self._set_exchange(exchange, duration_mult=1.0, intensity=intensity)
                self.last_combo = combo
                self.misses_in_row = 0
                return
        
        # Ambient exchange (15% chance - breaks repetition)
        if random.random() < 0.15:
            exchange = self._pick_exchange(AMBIENT_EXCHANGES, intensity, "ambient")
            self._set_exchange(exchange, duration_mult=1.1, intensity=intensity)
            self.last_combo = combo
            self.misses_in_row = 0
            return
        
        # NLS-heavy exchange (12% chance - syntax→physicality catalog)
        if random.random() < 0.12:
            exchange = self._pick_exchange(NLS_EXCHANGE_POOL, intensity, "nls")
            self._set_exchange(exchange, duration_mult=1.2, intensity=intensity)
            self.last_combo = combo
            self.misses_in_row = 0
            return
        
        # Regular lane exchange
        lane_data = LANE_EXCHANGES.get(lane, LANE_A_EXCHANGES)
        pool = lane_data.get(tier, lane_data["building"])
        
        # Pick fresh exchange
        available = [e for e in pool if e not in self.recent_exchanges]
        if not available:
            available = pool
            self.recent_exchanges.clear()
        
        exchange = self._pick_exchange(available, intensity, "pool")
        self.recent_exchanges.append(exchange)
        if len(self.recent_exchanges) > 8:
            self.recent_exchanges.pop(0)
        
        # Quality affects timing and inner thought chance
        if quality == "perfect":
            duration_mult = 1.4
            inner_chance = 0.5
        elif quality == "great":
            duration_mult = 1.2
            inner_chance = 0.35
        else:
            duration_mult = 1.0
            inner_chance = 0.25
        
        self._set_exchange(exchange, duration_mult, inner_chance=inner_chance, intensity=intensity)
        
        self.last_combo = combo
        self.misses_in_row = 0
    
    def trigger_miss(self, lane: str, intensity: float, combo: int, grip: float):
        """Trigger dialogue for miss with context-aware decision tree"""
        # Set cascade trigger context
        self.set_trigger_context("miss", f"{lane}_grip{grip:.1f}")
        
        self.streak_before_miss = self.last_combo
        self.hits_since_miss = 0
        
        # Determine miss context using decision tree
        if grip <= 1.0:
            # Danger zone - slipping
            context = "slip_miss"
        elif self.misses_in_row > 1:
            # Multiple misses - recovery mode
            context = "recovery"
        elif self.misses_in_row > 0:
            # Second miss
            context = "recovery"
        elif self.current_mode == "gentle":
            # Gentle mode miss - softer
            context = "gentle_miss"
        elif self.current_mode == "rough":
            # Rough mode miss - more urgent
            context = "rough_miss"
        else:
            # First miss after streak
            context = "first_miss"
        
        exchanges = MISS_EXCHANGES.get(context, MISS_EXCHANGES["first_miss"])
        
        # Pick fresh miss exchange
        available = [e for e in exchanges if e not in self.recent_miss]
        if not available:
            available = exchanges
            self.recent_miss.clear()
        
        exchange = self._pick_exchange(available, intensity, "pool")
        self.recent_miss.append(exchange)
        if len(self.recent_miss) > 3:
            self.recent_miss.pop(0)
        
        self._set_exchange(exchange, duration_mult=0.8, inner_chance=0.4, intensity=intensity)
        
        self.misses_in_row += 1
        self.last_combo = 0
    
    def trigger_streak_loss(self, old_combo: int, intensity: float = 0.6):
        """Special dialogue when a big streak is broken"""
        if old_combo >= 20:
            context = "20_plus"
        elif old_combo >= 10:
            context = "10_to_19"
        elif old_combo >= 5:
            context = "5_to_9"
        else:
            return  # No special dialogue for small streaks
        
        exchanges = STREAK_LOSS.get(context, STREAK_LOSS["5_to_9"])
        exchange = self._pick_exchange(exchanges, intensity, "streak")
        self._set_exchange(exchange, duration_mult=1.3, always_inner=True, intensity=intensity)
    
    def _set_exchange(self, exchange: tuple, duration_mult: float = 1.0, 
                      always_inner: bool = False, inner_chance: float = 0.35,
                      intensity: float = 0.5):
        """Set the current exchange lines - LEAKS INTEGRATED NATURALLY"""
        fiend, bird, inner = exchange
        bird = self._maybe_prefix_trigger_interjection(bird)
        
        # Set Fiend line directly
        self.fiend_line = fiend
        self.fiend_timer = 1.5 * duration_mult
        
        # Normalize intensity from 0-100 scale to 0.0-1.0
        # Game uses 0-100, leak system expects 0.0-1.0
        normalized_intensity = intensity / 100.0 if intensity > 1.0 else intensity
        
        # Process Birdsong line through unified dialogue system for leakage
        if self.dialogue_engine and bird:
            processed = self.dialogue_engine.process_line("BIRDSONG", bird, normalized_intensity)
            
            # Collect leaks
            front_leaks = []
            back_leaks = []
            core_text = bird
            seen_core = False
            
            for speaker, text, meta in processed:
                if "_LEAK" in speaker:
                    if not seen_core:
                        front_leaks.append(text)
                    else:
                        back_leaks.append(text)
                else:
                    core_text = text
                    seen_core = True
            
            # Build INTEGRATED line - leaks are part of the speech, not separate
            # Front leak becomes an interjection at start
            # Back leak becomes a trailing reaction
            
            line_parts = []
            
            # Front leaks: "Oiii~— rest of line" or "Gah— rest of line"
            if front_leaks:
                front = " ".join(front_leaks)
                # Add em-dash if the leak doesn't already have trailing punctuation
                if not front.endswith(("~", "—", "!", "?", ".")):
                    front = front + "—"
                line_parts.append(front)
            
            # Core text (strip any existing quotes, we'll add our own)
            core_clean = core_text.strip('"').strip()
            line_parts.append(core_clean)
            
            # Back leaks: "line ending *squirm*" or "line hahhh~"
            if back_leaks:
                back = " ".join(back_leaks)
                line_parts.append(back)
            
            # Combine into single quoted line
            combined = " ".join(line_parts)
            self.bird_line = combined  # No quotes here, render adds them
            self.bird_timer = 2.0 * duration_mult
            
            # Track for any special rendering needs
            self.has_leak = bool(front_leaks or back_leaks)
        else:
            self.bird_line = bird if bird else ""
            self.bird_timer = 2.0 * duration_mult
            self.has_leak = False
        
        # Clear the separate leak line (now integrated)
        self.leak_line = ""
        self.leak_timer = 0
        
        # Inner thoughts: always for milestones, else chance-based
        if always_inner or random.random() < inner_chance:
            self.inner_line = inner
            self.inner_timer = 2.5 * duration_mult
        else:
            self.inner_line = ""
            self.inner_timer = 0
        
        # ═══════════════════════════════════════════════════════════════════
        # CASCADE TRACKING - Record both lines when exchange is set
        # ═══════════════════════════════════════════════════════════════════
        if self.fiend_line:
            self._record_to_cascade("FIEND", self.fiend_line)
        if self.bird_line:
            self._record_to_cascade("BIRDSONG", self.bird_line)
    
    def queue_line(self, speaker: str, text: str, duration: float = 2.0):
        """Queue a single line from dynamic dialogue systems - LEAKS INTEGRATED"""
        if speaker == "FIEND":
            self.fiend_line = text
            self.fiend_timer = duration
            # Record to cascade
            self._record_to_cascade("FIEND", text)
            # Auto-voice (optional)
            try:
                am = getattr(self, 'audio_manager', None) or _lk_am()
                if am:
                    if text != self._last_voice_text.get("FIEND", ""):
                        self._voice_seq["FIEND"] = int(self._voice_seq.get("FIEND", 0)) + 1
                        self._last_voice_text["FIEND"] = text
                    tok = f'FIEND:{self._voice_seq.get("FIEND", 0)}'
                    self._voice_any_line("FIEND", text)
            except Exception:
                pass
        elif speaker == "BIRDSONG":
            # Process through unified system
            if self.dialogue_engine:
                processed = self.dialogue_engine.process_line("BIRDSONG", text)
                
                front_leaks = []
                back_leaks = []
                core_text = text
                seen_core = False
                
                for s, t, m in processed:
                    if "_LEAK" in s:
                        if not seen_core:
                            front_leaks.append(t)
                        else:
                            back_leaks.append(t)
                    else:
                        core_text = t
                        seen_core = True
                
                # Build INTEGRATED line - no brackets
                line_parts = []
                
                if front_leaks:
                    front = " ".join(front_leaks)
                    if not front.endswith(("~", "—", "!", "?", ".")):
                        front = front + "—"
                    line_parts.append(front)
                
                line_parts.append(core_text.strip('"').strip())
                
                if back_leaks:
                    line_parts.append(" ".join(back_leaks))
                
                self.bird_line = " ".join(line_parts)
                self.bird_timer = duration
                self.has_leak = bool(front_leaks or back_leaks)
                # Record to cascade
                self._record_to_cascade("BIRDSONG", self.bird_line)
                # Auto-voice (optional)
                try:
                    am = getattr(self, 'audio_manager', None) or _lk_am()
                    if am:
                        inten = max(0.0, min(1.0, float(getattr(self, "sync_level", 50.0)) / 100.0))
                        line = self.bird_line
                        if line != self._last_voice_text.get("BIRDSONG", ""):
                            self._voice_seq["BIRDSONG"] = int(self._voice_seq.get("BIRDSONG", 0)) + 1
                            self._last_voice_text["BIRDSONG"] = line
                        tok = f'BIRDSONG:{self._voice_seq.get("BIRDSONG", 0)}'
                        self._voice_any_line("BIRDSONG", line)
                except Exception:
                    pass
            else:
                self.bird_line = text
                self.bird_timer = duration
                self.has_leak = False
                # Record to cascade
                self._record_to_cascade("BIRDSONG", text)
                # Auto-voice (optional)
                try:
                    am = getattr(self, 'audio_manager', None) or _lk_am()
                    if am:
                        inten = max(0.0, min(1.0, float(getattr(self, "sync_level", 50.0)) / 100.0))
                        line = text
                        if line != self._last_voice_text.get("BIRDSONG", ""):
                            self._voice_seq["BIRDSONG"] = int(self._voice_seq.get("BIRDSONG", 0)) + 1
                            self._last_voice_text["BIRDSONG"] = line
                        tok = f'BIRDSONG:{self._voice_seq.get("BIRDSONG", 0)}'
                        self._voice_any_line("BIRDSONG", line)
                except Exception:
                    pass
        elif speaker == "NARRATOR":
            self.inner_line = text
            self.inner_timer = duration * 1.2
            # Auto-voice (optional)
            try:
                am = getattr(self, 'audio_manager', None) or _lk_am()
                if am:
                    if text != self._last_voice_text.get("NARRATOR", ""):
                        self._voice_seq["NARRATOR"] = int(self._voice_seq.get("NARRATOR", 0)) + 1
                        self._last_voice_text["NARRATOR"] = text
                    tok = f'NARRATOR:{self._voice_seq.get("NARRATOR", 0)}'
                    self._voice_any_line("NARRATOR", text)
            except Exception:
                pass
    
    def update(self, dt: float):
        self.fiend_timer = max(0, self.fiend_timer - dt)
        self.bird_timer = max(0, self.bird_timer - dt)
        self.inner_timer = max(0, self.inner_timer - dt)
        self.leak_timer = max(0, self.leak_timer - dt)
        
        if self.fiend_timer <= 0:
            self.fiend_line = ""
        if self.bird_timer <= 0:
            self.bird_line = ""
        if self.inner_timer <= 0:
            self.inner_line = ""
        if self.leak_timer <= 0:
            self.leak_line = ""
        
        # Process queued lines (for reciprocity responses)
        if self.queued_lines and self.fiend_timer <= 0 and self.bird_timer <= 0:
            speaker, text = self.queued_lines.pop(0)
            self.queue_line(speaker, text, 2.0)
    
    def render(self, scr, y: int, w: int, cx: int):
        """Render dialogue lines - leaks integrated naturally into Birdsong's speech"""
        try:
            # Fiend line (quoted)
            fiend_text = f'"{self.fiend_line}"' if self.fiend_line else ""
            
            # Bird line has leaks integrated: "Oiii~— I hate you! *squirm*"
            # Add quotes around the whole thing
            bird_text = f'"{self.bird_line}"' if self.bird_line else ""
            
            # Calculate centered positions with gap between speakers
            gap = 6
            total_w = len(fiend_text) + gap + len(bird_text)
            start_x = cx - total_w // 2
            
            # Fiend (left of center, yellow)
            if self.fiend_line and self.fiend_timer > 0:
                alpha = min(1.0, self.fiend_timer / 0.5)
                attr = curses.color_pair(1) | curses.A_BOLD
                if alpha < 0.5:
                    attr |= curses.A_DIM
                scr.addstr(y, max(2, start_x), fiend_text, attr)
                # Track for reciprocity
                self.last_displayed = ("FIEND", self.fiend_line)
            
            # Bird with integrated leaks (right of center, white)
            # Leaks are now part of the line, not visually separate
            if self.bird_line and self.bird_timer > 0:
                bird_x = start_x + len(fiend_text) + gap if self.fiend_line else cx - len(bird_text) // 2
                alpha = min(1.0, self.bird_timer / 0.5)
                attr = curses.color_pair(2)
                if alpha < 0.5:
                    attr |= curses.A_DIM
                
                x_pos = max(2, min(bird_x, w - len(bird_text) - 2))
                scr.addstr(y, x_pos, bird_text, attr)
                # Track for reciprocity
                self.last_displayed = ("BIRDSONG", self.bird_line)
            
            # Inner thoughts (row below, center, dim)
            if self.inner_line and self.inner_timer > 0:
                inner_text = f"*{self.inner_line}*"
                x = cx - len(inner_text) // 2
                attr = curses.color_pair(5) | curses.A_DIM
                scr.addstr(y + 1, max(2, x), inner_text, attr)
        except:
            pass

