        roll = random.random()
        if momentum > 0.3:
            category = "escalate" if roll < 0.7 else "redirect"
        elif momentum < -0.1:
            category = "turnabout" if roll < 0.6 else "redirect"
        else:
            category = random.choice(["escalate", "redirect", "turnabout"])
        
        if key in TRANSCEND_DIALOGUE and category in TRANSCEND_DIALOGUE[key]:
            return random.choice(TRANSCEND_DIALOGUE[key][category])
