        #           impatient, devoted goat-man waiting at the door
        # ═══════════════════════════════════════════════════════════════════════
        
        goat_eligible = (
            self.trust.unlocked_hump_dog and           # Trust unlocked (vulnerability >= 50)
            self.vibe.bathroom_trips >= 3 and          # 3+ bathroom trips
            self.profile.total_sessions >= 2 and       # Returning player
            self.round_state.surge_tier >= 3 and       # Has PERFECT LINE ready (surge gate)
            random.random() < 0.25                     # 25% when eligible
        )
        
        if goat_eligible:
            # Spend the surge for this special moment
            self.round_state.use_surge("choice")  # Costs 2 tiers (perfect line cost)
            self.pending_notifications.append("🐐 HUMP-DOG UNLOCKED 🐐")
            return self._do_hump_dog()
        
        # Normal bathroom sequence
